const formatLabel = (value: string | null | undefined, labels?: Record<string, string>): string => {
    if (!value) return "\u2014"
    if (labels && labels[value]) return labels[value]
    return value.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())
}

function formatDocumentsAvailableSummary(raw: unknown): string | null {
    if (!Array.isArray(raw) || raw.length === 0) return null
    const statusShort: Record<string, string> = {
        in_custody: "In custody",
        can_obtain: "Can help obtain",
        unknown: "Unknown",
    }
    if (typeof raw[0] === "object" && raw[0] !== null && "type" in (raw[0] as object)) {
        return (raw as { type: string; status: string }[])
            .map((e) => `${formatLabel(e.type)} — ${statusShort[e.status] || e.status}`)
            .join("; ")
    }
    return (raw as string[])
        .filter((d) => d !== "none_available")
        .map((d) => formatLabel(d))
        .join(", ")
}

