const DOCUMENT_INVENTORY_STATUS_SHORT: Record<string, string> = {
    in_custody: "In custody",
    can_obtain: "Can help obtain",
    unknown: "Unknown",
}

type DocumentInventoryStatus = "in_custody" | "can_obtain" | "unknown"

function parseDocumentsInventoryMap(raw: unknown): Record<string, DocumentInventoryStatus> {
    const map: Record<string, DocumentInventoryStatus> = {}
    if (!Array.isArray(raw)) return map
    if (raw.length > 0 && typeof raw[0] === "object" && raw[0] !== null && "type" in (raw[0] as object)) {
        for (const e of raw as { type: string; status: string }[]) {
            if (e.type && (e.status === "in_custody" || e.status === "can_obtain" || e.status === "unknown")) {
                map[e.type] = e.status
            }
        }
    }
    return map
}

function defaultDocumentRequestSelection(_inventory: Record<string, DocumentInventoryStatus>): Record<string, boolean> {
    const sel: Record<string, boolean> = {}
    for (const { value } of DOCUMENT_REQUEST_TYPE_OPTIONS) {
        sel[value] = false
    }
    return sel
}

function documentInventoryItemReceived(
    docType: string,
    uploaded: { document_type?: string | null }[],
    requestItems: { document_type: string; item_status: string }[]
): boolean {
    if (uploaded.some((d) => d.document_type === docType)) return true
    return requestItems.some(
        (i) => i.document_type === docType && (i.item_status === "uploaded" || i.item_status === "replaced")
    )
}

const DocumentInventoryTable = ({
    inventory,
    uploadedDocuments,
    requestItems = [],
}: {
    inventory: Record<string, DocumentInventoryStatus>
    uploadedDocuments: { document_type?: string | null }[]
    requestItems?: { document_type: string; item_status: string }[]
}) => {
    const rows = DOCUMENT_REQUEST_TYPE_OPTIONS.map((opt) => {
        const status = inventory[opt.value]
        if (status !== "in_custody" && status !== "can_obtain") return null
        return {
            key: opt.value,
            label: opt.label,
            inCustody: status === "in_custody",
            canObtain: status === "can_obtain",
            received: documentInventoryItemReceived(opt.value, uploadedDocuments, requestItems),
        }
    }).filter(Boolean) as { key: string; label: string; inCustody: boolean; canObtain: boolean; received: boolean }[]

    if (rows.length === 0) return null

    const markCell = (on: boolean) => (
        <span style={{ color: on ? COLORS.success : COLORS.ashMuted, fontWeight: on ? 700 : 400 }}>{on ? "\u2713" : "\u2014"}</span>
    )

    const thStyle: React.CSSProperties = {
        textAlign: "left",
        padding: "8px 10px",
        fontSize: "11px",
        fontWeight: 600,
        fontFamily: FONT,
        color: COLORS.ashMuted,
        textTransform: "uppercase",
        letterSpacing: "0.04em",
        borderBottom: `1px solid ${COLORS.ashSubtle}`,
    }
    const tdStyle: React.CSSProperties = {
        padding: "8px 10px",
        fontSize: "13px",
        fontFamily: FONT,
        color: "var(--foreground)",
        borderBottom: `1px solid ${COLORS.ashSubtle}`,
        verticalAlign: "middle",
    }

    return (
        <div style={{ marginBottom: "12px" }}>
            <div style={{ fontSize: "11px", fontWeight: 600, fontFamily: FONT, color: COLORS.ashMuted, textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: "8px" }}>
                Document inventory (at submission)
            </div>
            <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                    <thead>
                        <tr>
                            <th style={thStyle}>Document</th>
                            <th style={{ ...thStyle, textAlign: "center" }}>Available upon request</th>
                            <th style={{ ...thStyle, textAlign: "center" }}>Exists (can obtain)</th>
                            <th style={{ ...thStyle, textAlign: "center" }}>Received</th>
                        </tr>
                    </thead>
                    <tbody>
                        {rows.map((row) => (
                            <tr key={row.key}>
                                <td style={tdStyle}>{row.label}</td>
                                <td style={{ ...tdStyle, textAlign: "center" }}>{markCell(row.inCustody)}</td>
                                <td style={{ ...tdStyle, textAlign: "center" }}>{markCell(row.canObtain)}</td>
                                <td style={{ ...tdStyle, textAlign: "center" }}>
                                    {row.received ? (
                                        <span style={{ fontSize: "12px", fontWeight: 600, color: COLORS.success }}>Received</span>
                                    ) : (
                                        markCell(false)
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    )
}

function documentRequestLabel(documentType: string): string {
    return DOCUMENT_REQUEST_TYPE_OPTIONS.find((o) => o.value === documentType)?.label ?? formatLabel(documentType)
}

const DOCUMENT_REQUEST_ITEM_STATUS_LABELS: Record<string, string> = {
    requested: "Requested",
    uploaded: "Received",
    waived: "Waived",
    insufficient: "Needs replacement",
    replaced: "Replaced",
}

function documentRequestItemStatusColor(status: string): string {
    switch (status) {
        case "uploaded":
            return COLORS.moonstone
        case "waived":
            return COLORS.ashMuted
        case "insufficient":
            return COLORS.tangerine
        case "replaced":
            return COLORS.moonstone
        default:
            return COLORS.ash
    }
}

type ActivityLogEntry = {
    activity_type: string
    details: Record<string, unknown>
}

function activityLogEntryLabel(entry: ActivityLogEntry): string {
    const isStatus = entry.activity_type === "status_change"
    const fromStatus = entry.details?.previous_status as string | undefined
    const toStatus = entry.details?.status as string | undefined
    if (isStatus && (fromStatus || toStatus)) {
        return `${fromStatus ? formatLabel(fromStatus) : "—"} → ${toStatus ? formatLabel(toStatus) : "—"}`
    }
    switch (entry.activity_type) {
        case "section_note":
            return "Section note added"
        case "message":
            return "Message sent"
        case "referral_viewed":
            return "Referral viewed"
        case "referral_submitted":
            return "Referral submitted"
        case "assignment_changed":
            return "Assignment changed"
        case "section_status_changed":
            return "Section status updated"
        case "share_link_created":
            return "Share link created"
        case "share_link_revoked":
            return "Share link revoked"
        case "roi_share_link_created":
            return "ROI signing link created"
        case "roi_signing_started":
            return "ROI signing started"
        case "roi_signed":
            return "ROI signed (PDF stored)"
        case "document_request_sent":
            return "Document request sent"
        case "document_request_item_updated": {
            const docType = entry.details?.document_type as string | undefined
            const st = entry.details?.item_status as string | undefined
            const label = docType ? documentRequestLabel(docType) : "Document"
            const stLabel = st ? DOCUMENT_REQUEST_ITEM_STATUS_LABELS[st] || formatLabel(st) : ""
            return stLabel ? `${label}: ${stLabel}` : "Document request item updated"
        }
        case "document_request_items_uploaded": {
            const types = entry.details?.document_types
            const n = entry.details?.item_count
            if (Array.isArray(types) && types.length > 0) {
                const names = (types as string[]).map((t) => documentRequestLabel(t)).join(", ")
                return `Source uploaded: ${names}${typeof n === "number" ? ` (${n})` : ""}`
            }
            return "Source upload matched document request"
        }
        default:
            return entry.activity_type.replace(/_/g, " ")
    }
}

function activityTypeBadgeLabel(activityType: string): string {
    const labels: Record<string, string> = {
        referral_submitted: "Submitted",
        status_change: "Status",
        section_status_changed: "Status",
        message: "Message",
        assignment_changed: "Assignment",
        section_note: "Note",
        share_link_created: "Share",
        share_link_revoked: "Share",
        roi_share_link_created: "ROI",
        roi_signing_started: "ROI",
        roi_signed: "ROI",
        document_request_sent: "Documents",
        document_request_item_updated: "Documents",
        document_request_items_uploaded: "Documents",
    }
    if (labels[activityType]) return labels[activityType]
    if (activityType.startsWith("document_")) return "Documents"
    if (activityType.startsWith("roi_")) return "ROI"
    if (activityType.startsWith("share_link_")) return "Share"
    return activityType.replace(/_/g, " ")
}

function activityTypeBadgeColors(activityType: string): { text: string; bg: string } {
    if (activityType === "message") return { text: COLORS.infoText, bg: COLORS.infoBg }
    if (activityType === "referral_submitted") return { text: COLORS.greenText, bg: COLORS.green }
    if (activityType === "status_change" || activityType === "section_status_changed") {
        return { text: COLORS.moonstone, bg: COLORS.moonstoneLight }
    }
    if (activityType === "assignment_changed") return { text: "var(--foreground)", bg: COLORS.moonstoneLight }
    return { text: COLORS.ashMuted, bg: COLORS.coconut25 }
}

type ActivityFeedTypeFilter =
    | "all"
    | "status_change"
    | "message"
    | "assignment_changed"
    | "section_note"
    | "referral_submitted"
    | "documents"

function matchesActivityFeedTypeFilter(activityType: string, filter: ActivityFeedTypeFilter): boolean {
    if (filter === "all") return true
    if (filter === "documents") {
        return (
            activityType.startsWith("document_") ||
            activityType.startsWith("roi_") ||
            activityType.startsWith("share_link_")
        )
    }
    if (filter === "status_change") {
        return activityType === "status_change" || activityType === "section_status_changed"
    }
    return activityType === filter
}

