/** Table column: MC, MH, ML, SL (full name in title). */
const PROGRAM_TABLE_ABBREV_BY_NAME: Record<string, string> = {
    "monarch competency": "MC",
    "mental health": "MH",
    "monarch launch": "ML",
    "monarch mental health": "MH",
    "sober living": "SL",
    "monarch sober living": "SL",
}

const PROGRAM_TABLE_ABBREV_BY_ID: Record<string, string> = {
    prog_competency: "MC",
    prog_mental_health: "MH",
    prog_launch: "ML",
    prog_sober_living: "SL",
}

function submissionProgramTableDisplay(
    row: Pick<ReferralSubmission, "current_program_id" | "intended_program_id" | "origin_program_id">,
    programNamesById: Record<string, string>
): { abbrev: string; full: string } {
    const id = row.current_program_id || row.intended_program_id || row.origin_program_id
    const full = submissionProgramDisplay(row, programNamesById)
    if (!id || full === "\u2014") return { abbrev: "\u2014", full }
    const byId = PROGRAM_TABLE_ABBREV_BY_ID[id]
    if (byId) return { abbrev: byId, full }
    const byName = PROGRAM_TABLE_ABBREV_BY_NAME[full.toLowerCase().trim()]
    if (byName) return { abbrev: byName, full }
    const lower = full.toLowerCase()
    if (lower.includes("competency")) return { abbrev: "MC", full }
    if (lower.includes("mental health")) return { abbrev: "MH", full }
    if (lower.includes("launch")) return { abbrev: "ML", full }
    if (lower.includes("sober")) return { abbrev: "SL", full }
    return { abbrev: full.length > 6 ? `${full.slice(0, 5)}\u2026` : full, full }
}

/** Postgres `date` / YYYY-MM-DD: local calendar day. Timestamps: local datetime. */
const formatDate = (date: string | null | undefined): string => {
    if (!date) return "\u2014"
    const s = String(date).trim()
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
        const [y, mo, d] = s.split("-").map((part) => parseInt(part, 10))
        return new Date(y, mo - 1, d).toLocaleDateString("en-US", {
            month: "short",
            day: "numeric",
            year: "numeric",
        })
    }
    return new Date(s).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
    })
}

async function readEdgeFunctionInvokeError(err: unknown): Promise<string> {
    if (!err || typeof err !== "object") return String(err ?? "Unknown error")
    const e = err as { message?: string; context?: { json?: () => Promise<unknown> } }
    if (e.context && typeof e.context.json === "function") {
        try {
            const body = (await e.context.json()) as { error?: string; details?: string }
            if (body?.error && body?.details) return `${body.error}: ${body.details}`
            if (body?.error) return body.error
        } catch {
            // ignore parse errors
        }
    }
    if (e.message) return e.message
    return "Edge function error"
}

