function ProgramDashboardLogo({
    src,
    alt,
    widthPx,
    heightPx,
    fallbackLabel,
}: {
    src: string
    alt: string
    widthPx: number
    heightPx: number
    fallbackLabel: string
}) {
    const [failed, setFailed] = useState(false)
    const box: React.CSSProperties = {
        display: "block",
        width: widthPx,
        height: heightPx,
        marginBottom: 8,
        flexShrink: 0,
    }
    if (failed) {
        return (
            <div
                aria-hidden
                style={{
                    ...box,
                    borderRadius: 8,
                    background: COLORS.coconut50,
                    border: `1px solid ${COLORS.ashSubtle}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 11,
                    fontWeight: 600,
                    color: COLORS.ashMuted,
                    fontFamily: FONT,
                }}
            >
                {fallbackLabel.slice(0, 2).toUpperCase()}
            </div>
        )
    }
    return (
        <img
            src={src}
            alt={alt}
            width={widthPx}
            height={heightPx}
            style={{
                ...box,
                objectFit: "contain",
                objectPosition: "left center",
            }}
            onError={() => setFailed(true)}
        />
    )
}

