// ============================================================================
// EXPORT UTILITIES
// ============================================================================

const downloadFile = (content: string, filename: string, mimeType: string) => {
    const blob = new Blob([content], { type: mimeType })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = filename
    a.click()
    URL.revokeObjectURL(url)
}

const escapeCSV = (val: unknown): string => {
    if (val == null) return ""
    const str = typeof val === "object" ? JSON.stringify(val) : String(val)
    if (str.includes(",") || str.includes('"') || str.includes("\n") || str.includes("\r")) {
        return `"${str.replace(/"/g, '""')}"`
    }
    return str
}

const formatDateForRitten = (value: unknown): string => {
    if (!value) return ""
    const s = String(value).trim()
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/)
    if (m) return `${m[1]}-${m[2]}-${m[3]}`
    const date = new Date(s)
    if (Number.isNaN(date.getTime())) return ""
    const y = date.getFullYear()
    const mo = String(date.getMonth() + 1).padStart(2, "0")
    const d = String(date.getDate()).padStart(2, "0")
    return `${y}-${mo}-${d}`
}

const normalizeBirthSex = (value: unknown, fallback?: unknown): string => {
    const raw = String(value ?? fallback ?? "").trim().toLowerCase()
    if (raw === "male") return "Male"
    if (raw === "female") return "Female"
    return ""
}

const resolveMemberId = (row: ReferralSubmission): string => {
    const medicaid = String(row.medicaid_number ?? "").trim()
    if (medicaid) return medicaid
    const medicare = String(row.medicare_number ?? "").trim()
    if (medicare) return medicare
    const details = String(row.private_insurance_details ?? "")
    const parsed = details.match(/\b([A-Z0-9]{6,})\b/)
    return parsed?.[1] ?? ""
}

const exportRittenCSV = (data: ReferralSubmission[], filename: string) => {
    const columns = ["First Name", "Last Name", "Date of Birth", "Birth Sex", "Diagnosis", "Payer", "Member ID"]
    const header = columns.join(",")
    const rows = data.map((row) => {
        const mapped = {
            "First Name": String(row.client_first_name ?? "").trim(),
            "Last Name": String(row.client_last_name ?? "").trim(),
            "Date of Birth": formatDateForRitten(row.client_dob),
            "Birth Sex": normalizeBirthSex(row.client_sex_at_birth, row.client_gender),
            "Diagnosis": String(row.current_diagnoses ?? "").trim(),
            "Payer": "self",
            "Member ID": resolveMemberId(row),
        }
        return columns.map((col) => escapeCSV((mapped as any)[col])).join(",")
    })
    downloadFile([header, ...rows].join("\n"), filename, "text/csv")
}

const getRittenWarnings = (data: ReferralSubmission[]) => {
    const counts = {
        missingFirstName: 0,
        missingLastName: 0,
        missingDOB: 0,
        missingBirthSex: 0,
        missingDiagnosis: 0,
        missingMemberId: 0,
    }
    for (const row of data) {
        if (!String(row.client_first_name ?? "").trim()) counts.missingFirstName += 1
        if (!String(row.client_last_name ?? "").trim()) counts.missingLastName += 1
        if (!formatDateForRitten(row.client_dob)) counts.missingDOB += 1
        if (!normalizeBirthSex(row.client_sex_at_birth, row.client_gender)) counts.missingBirthSex += 1
        if (!String(row.current_diagnoses ?? "").trim()) counts.missingDiagnosis += 1
        if (!resolveMemberId(row)) counts.missingMemberId += 1
    }
    return counts
}

function staffAssigneeExportFields(
    row: ReferralSubmission,
    byUserId: Record<string, AdmissionsStaffProfile | undefined> | undefined
) {
    const uid = row.assigned_to_user_id
    const a = uid && byUserId ? byUserId[uid] : undefined
    return {
        assigned_to_user_id: uid ?? "",
        assigned_staff_display_name: a?.display_name != null ? String(a.display_name) : "",
        assigned_staff_title: a?.title != null ? String(a.title) : "",
        assigned_staff_phone: a?.phone != null ? String(a.phone) : "",
        assigned_staff_contact_email: a?.contact_email != null ? String(a.contact_email) : "",
    }
}

interface SectionNoteRow {
    id: string
    section_key: string
    author_email: string | null
    content: string
    is_internal: boolean
    created_at: string
}

const SECTION_NOTE_KEYS = [
    { value: "client", label: "Client" },
    { value: "source", label: "Referral source" },
    { value: "contacts", label: "Contacts" },
    { value: "documents", label: "Documents" },
    { value: "inventory", label: "Document inventory" },
    { value: "legal", label: "Legal / court" },
    { value: "location", label: "Location / facility" },
    { value: "risk", label: "Risk assessment" },
    { value: "clinical", label: "Mental health & clinical" },
    { value: "substance", label: "Substance use" },
    { value: "medical", label: "Medical / somatic" },
    { value: "insurance", label: "Insurance / benefits" },
    { value: "urgency", label: "Urgency & notes" },
    { value: "other", label: "Other" },
] as const

const SECTION_NOTE_LEGACY_ALIASES: Record<string, string[]> = {
    other: ["general"],
}

const SECTION_NOTE_LEGACY_LABELS: Record<string, string> = {
    general: "General (legacy)",
}

function sectionNoteLabel(key: string): string {
    const match = SECTION_NOTE_KEYS.find((k) => k.value === key)
    if (match) return match.label
    return SECTION_NOTE_LEGACY_LABELS[key] || formatLabel(key)
}

function notesForSection(notes: SectionNoteRow[], sectionKey: string): SectionNoteRow[] {
    const aliases = SECTION_NOTE_LEGACY_ALIASES[sectionKey] || []
    return notes.filter((n) => n.section_key === sectionKey || aliases.includes(n.section_key))
}

function formatSectionNotesCsvCell(notes: SectionNoteRow[], sectionKey: string): string {
    return notesForSection(notes, sectionKey)
        .map((n) => {
            const prefix = n.is_internal ? "[Internal] " : ""
            const who = n.author_email || "—"
            return `${prefix}[${formatDate(n.created_at)}] ${who}: ${n.content}`
        })
        .join("\n\n")
}

function escapePrintHtml(text: string): string {
    return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
}

function formatSectionNotesPdfHtml(notes: SectionNoteRow[], sectionKey: string): string {
    const items = notesForSection(notes, sectionKey)
    if (items.length === 0) return ""
    const blocks = items
        .map((n) => {
            const internal = n.is_internal ? '<span style="font-size:10px;font-weight:600;text-transform:uppercase">Internal · </span>' : ""
            const meta = `${internal}${escapePrintHtml(n.author_email || "—")} · ${formatDate(n.created_at)}`
            return `<div class="section-note"><div class="section-note-meta">${meta}</div><div class="notes">${escapePrintHtml(n.content || "")}</div></div>`
        })
        .join("")
    return `<div class="section-notes-block"><div class="section-notes-label">Section notes</div>${blocks}</div>`
}

const exportSubmissionSectionNotesCsv = (referralId: string, notes: SectionNoteRow[], filename: string) => {
    const columns = ["referral_id", "section_key", "section_label", "author_email", "is_internal", "created_at", "content"] as const
    const header = columns.join(",")
    const rows = notes.map((n) =>
        [
            escapeCSV(referralId),
            escapeCSV(n.section_key),
            escapeCSV(sectionNoteLabel(n.section_key)),
            escapeCSV(n.author_email),
            escapeCSV(n.is_internal ? "true" : "false"),
            escapeCSV(n.created_at),
            escapeCSV(n.content),
        ].join(",")
    )
    downloadFile([header, ...rows].join("\n"), filename, "text/csv")
}

const exportSubmissionsCSV = (
    data: ReferralSubmission[],
    filename: string,
    assigneeByUserId?: Record<string, AdmissionsStaffProfile | undefined>,
    notesByReferralId?: Record<string, SectionNoteRow[]>
) => {
    const assigneeColumns = [
        "assigned_to_user_id",
        "assigned_staff_display_name",
        "assigned_staff_title",
        "assigned_staff_phone",
        "assigned_staff_contact_email",
    ] as const
    const columns = [
        "id", "admin_ref_id", "referral_code", "referral_source_type", "is_priority_referral", "referral_source_name",
        "referral_source_email", "referral_source_phone", "referral_source_organization",
        "referral_source_title", "urgent_placement", "can_provide_collateral", "previous_monarch_referral",
        // Demographics
        "client_first_name", "client_middle_name", "client_last_name", "client_dob", "client_ssn",
        "client_gender", "client_sex_at_birth", "client_pronouns", "client_preferred_name",
        "client_primary_language", "client_english_proficiency", "interpreter_needed",
        "client_ethnicity", "client_marital_status", "client_phone", "client_email",
        "client_consents_to_referral",
        // Contacts
        "emergency_contact_name", "emergency_contact_relationship", "emergency_contact_phone",
        "emergency_contact_can_provide_info", "additional_contacts",
        // Documents
        "documents_available", "documents_notes",
        // Insurance
        "medicaid_status", "medicaid_number", "medicare_status", "medicare_number",
        "has_private_insurance", "private_insurance_details", "ssdi_status", "benefits_notes",
        // Legal
        "case_number", "court_jurisdiction", "judge_name", "courtroom", "attorney_name",
        "attorney_phone", "attorney_email", "charges", "competency_status", "competency_eval_date",
        "competency_evaluator", "next_court_date", "on_probation", "probation_officer_contact",
        "on_parole", "parole_officer_contact", "active_warrants", "has_bond_holds",
        "bond_holds_details", "pr_bond_to_monarch",
        // Location
        "current_location_type", "facility_name", "facility_address", "inmate_id",
        "facility_contact_person", "facility_contact_phone", "currently_incarcerated",
        "expected_release_date", "housing_prior", "housing_post_program", "housing_notes",
        // Clinical
        "current_diagnoses", "medication_compliance", "current_medications", "medication_barriers",
        "psychiatric_history", "previous_treatment_programs", "tbi_history", "tbi_details",
        "idd_status", "idd_details",
        // Substance
        "substance_use_pattern", "substance_use_current", "substance_use_history",
        "detox_required", "detox_details",
        // Medical
        "medical_conditions", "medical_conditions_controlled", "medications_non_psychiatric",
        "medication_allergies", "mobility_needs", "adl_support_needed", "adl_support_details",
        "acute_medical_needs",
        // Safety
        "violence_risk", "violence_risk_details", "suicide_risk", "suicide_risk_details",
        "elopement_risk", "elopement_risk_details", "arson_history", "arson_details",
        "rso_status", "rso_details", "medical_needs", "safety_notes",
        // Urgency
        "urgency_level", "urgency_reason", "additional_notes", "referral_source_channel",
        // System
        "status", "reviewed_by", "reviewed_at", "review_notes", "created_at", "updated_at",
        ...assigneeColumns,
    ]
    const noteColumns = notesByReferralId ? SECTION_NOTE_KEYS.map((k) => `notes_${k.value}`) : []
    const allColumns = [...columns, ...noteColumns]
    const header = allColumns.join(",")
    const rows = data.map((row) => {
        const assignee = staffAssigneeExportFields(row, assigneeByUserId)
        const merged = { ...row, ...assignee }
        const base = columns.map((col) => escapeCSV((merged as Record<string, unknown>)[col]))
        const noteCells = noteColumns.map((col) => {
            const sectionKey = col.replace(/^notes_/, "")
            const notes = notesByReferralId?.[row.id] ?? []
            return escapeCSV(formatSectionNotesCsvCell(notes, sectionKey))
        })
        return [...base, ...noteCells].join(",")
    })
    downloadFile([header, ...rows].join("\n"), filename, "text/csv")
}

const exportInquiriesCSV = (data: ReferralInquiry[], filename: string) => {
    const columns = [
        "id", "inquiry_type", "referral_source_name", "referral_source_phone",
        "referral_source_email", "referral_source_relationship", "referral_source_organization",
        "referral_source_title", "client_first_name", "client_last_initial",
        "client_approximate_age", "client_current_location", "situation_notes",
        "how_heard_about_us", "status", "created_at", "updated_at",
    ]
    const header = columns.join(",")
    const rows = data.map((row) => columns.map((col) => escapeCSV((row as any)[col])).join(","))
    downloadFile([header, ...rows].join("\n"), filename, "text/csv")
}

const exportSubmissionPDF = (s: ReferralSubmission, assignee?: AdmissionsStaffProfile | null, notes: SectionNoteRow[] = []) => {
    const sn = (key: string) => formatSectionNotesPdfHtml(notes, key)
    const w = window.open("", "_blank")
    if (!w) return
    let assigneeHtml = ""
    if (s.assigned_to_user_id) {
        if (assignee && (assignee.display_name || assignee.title || assignee.contact_email || assignee.phone)) {
            assigneeHtml = `<h2>Admissions assignment</h2><div class="grid">
<div class="field"><strong>Name:</strong> ${assignee.display_name || "\u2014"}</div>
<div class="field"><strong>Title:</strong> ${assignee.title || "\u2014"}</div>
<div class="field"><strong>Email:</strong> ${assignee.contact_email || "\u2014"}</div>
<div class="field"><strong>Phone:</strong> ${formatPhone(assignee.phone || "")}</div>
</div>`
        } else {
            assigneeHtml = `<h2>Admissions assignment</h2><p class="meta">Assigned — no published profile on file yet (complete My profile on the referral dashboard).</p>`
        }
    }
    w.document.write(`<!DOCTYPE html><html><head>
<title>Referral \u2014 ${s.client_first_name} ${s.client_last_name}</title>
<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:"Montserrat",sans-serif;color:${COLORS.ash};padding:40px;max-width:800px;margin:0 auto}
h1{font-size:22px;font-weight:700;margin-bottom:4px}
h2{font-size:15px;font-weight:600;margin:24px 0 12px;padding-bottom:6px;border-bottom:2px solid ${COLORS.moonstone};color:${COLORS.gunmetal}}
.meta{font-size:12px;color:${COLORS.ashMuted};margin-bottom:20px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 32px}
.field{font-size:13px;margin-bottom:6px}
.field strong{font-weight:600}
.risk-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:8px 0}
.risk{text-align:center;padding:8px;border-radius:8px;font-size:11px;font-weight:600;text-transform:uppercase}
.risk-yes{background:${COLORS.tangerineLight};color:${COLORS.redText};border:1px solid ${COLORS.tangerine}}
.risk-no{background:${COLORS.coconut};color:${COLORS.ashMuted}}
.notes{background:${COLORS.coconut};padding:12px;border-radius:8px;font-size:13px;white-space:pre-wrap;margin-top:4px}
.section-notes-block{margin-top:16px;padding-top:12px;border-top:1px solid ${COLORS.ashSubtle}}
.section-notes-label{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.06em;color:${COLORS.ashMuted};margin-bottom:8px}
.section-note{margin-bottom:8px}
.section-note-meta{font-size:11px;color:${COLORS.ashMuted};margin-bottom:4px}
@media print{body{padding:20px}}
</style></head><body>
<h1>${s.client_first_name} ${s.client_middle_name || ""} ${s.client_last_name}</h1>
<div class="meta">${s.admin_ref_id || `ID: ${s.id}`} | Code: ${s.referral_code || "\u2014"} | Submitted: ${formatDate(s.created_at)} | Status: ${formatLabel(s.status)}</div>
${assigneeHtml}
<h2>Client Demographics</h2>
<div class="grid">
<div class="field"><strong>Aliases:</strong> ${s.client_preferred_name || "\u2014"}</div>
<div class="field"><strong>Date of Birth:</strong> ${formatDate(s.client_dob)}</div>
<div class="field"><strong>Gender:</strong> ${formatLabel(s.client_gender, GENDER_LABELS)}</div>
<div class="field"><strong>Sex at Birth:</strong> ${formatLabel(s.client_sex_at_birth)}</div>
<div class="field"><strong>Pronouns:</strong> ${formatLabel(s.client_pronouns)}</div>
<div class="field"><strong>SSN:</strong> ${maskSSN(s.client_ssn)}</div>
<div class="field"><strong>Primary Language:</strong> ${s.client_primary_language || "\u2014"}</div>
<div class="field"><strong>English Proficiency:</strong> ${formatLabel(s.client_english_proficiency)}</div>
<div class="field"><strong>Interpreter Needed:</strong> ${s.interpreter_needed ? "Yes" : "No"}</div>
<div class="field"><strong>Ethnicity:</strong> ${formatLabel(s.client_ethnicity)}</div>
<div class="field"><strong>Marital Status:</strong> ${formatLabel(s.client_marital_status)}</div>
<div class="field"><strong>Client Phone:</strong> ${formatPhone(s.client_phone)}</div>
<div class="field"><strong>Client Email:</strong> ${s.client_email || "\u2014"}</div>
<div class="field"><strong>Consents to Referral:</strong> ${formatLabel(s.client_consents_to_referral)}</div>
</div>
${sn("client")}
<h2>Referral Source</h2>
<div class="grid">
<div class="field"><strong>Name:</strong> ${s.referral_source_name}</div>
<div class="field"><strong>Type:</strong> ${formatLabel(s.referral_source_type, SOURCE_TYPE_LABELS)}</div>
<div class="field"><strong>Organization:</strong> ${s.referral_source_organization || "\u2014"}</div>
<div class="field"><strong>Title:</strong> ${s.referral_source_title || "\u2014"}</div>
<div class="field"><strong>Email:</strong> ${s.referral_source_email}</div>
<div class="field"><strong>Phone:</strong> ${formatPhone(s.referral_source_phone)}</div>
<div class="field"><strong>Can Provide Collateral:</strong> ${formatLabel(s.can_provide_collateral)}</div>
<div class="field"><strong>Previous Referral:</strong> ${formatLabel(s.previous_monarch_referral)}</div>
<div class="field"><strong>Expedited Placement:</strong> ${expeditedUrgentColumnLabel(s.urgent_placement, s.urgency_level) || "\u2014"}</div>
</div>
${sn("source")}
<h2>Legal / Court Information</h2>
<div class="grid">
<div class="field"><strong>Case Number:</strong> ${s.case_number || "\u2014"}</div>
<div class="field"><strong>Court Jurisdiction:</strong> ${s.court_jurisdiction || "\u2014"}</div>
<div class="field"><strong>Judge:</strong> ${s.judge_name || "\u2014"}</div>
<div class="field"><strong>Courtroom:</strong> ${s.courtroom || "\u2014"}</div>
<div class="field"><strong>Attorney:</strong> ${s.attorney_name || "\u2014"}</div>
<div class="field"><strong>Attorney Phone:</strong> ${formatPhone(s.attorney_phone)}</div>
<div class="field"><strong>Attorney Email:</strong> ${s.attorney_email || "\u2014"}</div>
<div class="field"><strong>Charges:</strong> ${s.charges || "\u2014"}</div>
<div class="field"><strong>Competency Status:</strong> ${formatLabel(s.competency_status, COMPETENCY_STATUS_LABELS)}</div>
<div class="field"><strong>Competency Eval Date:</strong> ${formatDate(s.competency_eval_date)}</div>
<div class="field"><strong>Evaluator:</strong> ${s.competency_evaluator || "\u2014"}</div>
<div class="field"><strong>Next Court Date:</strong> ${formatDate(s.next_court_date)}</div>
<div class="field"><strong>On Probation:</strong> ${s.on_probation ? "Yes" : "No"}</div>
${s.on_probation ? `<div class="field"><strong>PO Contact:</strong> ${s.probation_officer_contact || "\u2014"}</div>` : ""}
<div class="field"><strong>On Parole:</strong> ${s.on_parole ? "Yes" : "No"}</div>
${s.on_parole ? `<div class="field"><strong>Parole Contact:</strong> ${s.parole_officer_contact || "\u2014"}</div>` : ""}
<div class="field"><strong>Active Warrants:</strong> ${formatLabel(s.active_warrants)}</div>
<div class="field"><strong>Bond Holds:</strong> ${formatLabel(s.has_bond_holds)}</div>
${s.bond_holds_details ? `<div class="field"><strong>Bond Details:</strong> ${s.bond_holds_details}</div>` : ""}
<div class="field"><strong>PR Bond to Monarch:</strong> ${formatLabel(s.pr_bond_to_monarch)}</div>
</div>
${sn("legal")}
<h2>Current Location / Facility</h2>
<div class="grid">
<div class="field"><strong>Location Type:</strong> ${formatLabel(s.current_location_type, LOCATION_LABELS)}</div>
<div class="field"><strong>Facility:</strong> ${s.facility_name || "\u2014"}</div>
<div class="field"><strong>Address:</strong> ${s.facility_address || "\u2014"}</div>
<div class="field"><strong>Inmate ID:</strong> ${s.inmate_id || "\u2014"}</div>
<div class="field"><strong>Contact Person:</strong> ${s.facility_contact_person || "\u2014"}</div>
<div class="field"><strong>Contact Phone:</strong> ${formatPhone(s.facility_contact_phone)}</div>
<div class="field"><strong>Currently Incarcerated:</strong> ${s.currently_incarcerated ? "Yes" : "No"}</div>
${s.expected_release_date ? `<div class="field"><strong>Expected Release:</strong> ${formatDate(s.expected_release_date)}</div>` : ""}
<div class="field"><strong>Prior Housing:</strong> ${formatLabel(s.housing_prior)}</div>
<div class="field"><strong>Post-Program Housing:</strong> ${formatLabel(s.housing_post_program)}</div>
${s.housing_notes ? `<div class="field"><strong>Housing Notes:</strong> ${s.housing_notes}</div>` : ""}
</div>
${sn("location")}
<h2>Emergency Contact</h2>
<div class="grid">
<div class="field"><strong>Name:</strong> ${s.emergency_contact_name || "\u2014"}</div>
<div class="field"><strong>Relationship:</strong> ${s.emergency_contact_relationship || "\u2014"}</div>
<div class="field"><strong>Phone:</strong> ${formatPhone(s.emergency_contact_phone)}</div>
<div class="field"><strong>Can Provide Info:</strong> ${s.emergency_contact_can_provide_info ? "Yes" : "No"}</div>
</div>
${Array.isArray(s.additional_contacts) && s.additional_contacts.length > 0 ? `<h2>Additional Contacts</h2>${s.additional_contacts.map((c: any, i: number) => `<div class="grid"><div class="field"><strong>Contact ${i+1}:</strong> ${c.name || "\u2014"}</div><div class="field"><strong>Org:</strong> ${c.organization || "\u2014"}</div><div class="field"><strong>Contact:</strong> ${c.phone_email || "\u2014"}</div><div class="field"><strong>Role:</strong> ${c.role || "\u2014"}</div></div>`).join("")}` : ""}
${sn("contacts")}
<h2>Risk Assessment</h2>
<div class="risk-grid">
<div class="risk ${s.violence_risk && s.violence_risk !== "no_history" ? "risk-yes" : "risk-no"}">Violence: ${formatLabel(s.violence_risk, RISK_TIMEFRAME_LABELS)}</div>
<div class="risk ${s.suicide_risk && s.suicide_risk !== "no_history" ? "risk-yes" : "risk-no"}">Suicide: ${formatLabel(s.suicide_risk, RISK_TIMEFRAME_LABELS)}</div>
<div class="risk ${s.elopement_risk && s.elopement_risk !== "no_history" ? "risk-yes" : "risk-no"}">Elopement: ${formatLabel(s.elopement_risk, RISK_TIMEFRAME_LABELS)}</div>
<div class="risk ${s.medical_needs ? "risk-yes" : "risk-no"}">Medical: ${s.medical_needs ? "YES" : "NO"}</div>
</div>
${s.violence_risk_details ? `<div class="field"><strong>Violence Details:</strong></div><div class="notes">${s.violence_risk_details}</div>` : ""}
${s.suicide_risk_details ? `<div class="field"><strong>Suicide Details:</strong></div><div class="notes">${s.suicide_risk_details}</div>` : ""}
${s.elopement_risk_details ? `<div class="field"><strong>Elopement Details:</strong></div><div class="notes">${s.elopement_risk_details}</div>` : ""}
<div class="grid">
<div class="field"><strong>Arson History:</strong> ${formatLabel(s.arson_history)}</div>
${s.arson_details ? `<div class="field"><strong>Arson Details:</strong> ${s.arson_details}</div>` : ""}
<div class="field"><strong>RSO Status:</strong> ${formatLabel(s.rso_status)}</div>
${s.rso_details ? `<div class="field"><strong>RSO Details:</strong> ${s.rso_details}</div>` : ""}
</div>
${s.safety_notes ? `<div class="field"><strong>Safety Notes:</strong></div><div class="notes">${s.safety_notes}</div>` : ""}
${sn("risk")}
<h2>Clinical / Mental Health</h2>
<div class="field"><strong>Current Diagnoses:</strong></div><div class="notes">${s.current_diagnoses || "Not provided"}</div>
<div class="field" style="margin-top:12px"><strong>Medication Compliance:</strong> ${formatLabel(s.medication_compliance)}</div>
<div class="field" style="margin-top:12px"><strong>Current Medications:</strong></div><div class="notes">${formatMedications(s.current_medications)}</div>
${s.medication_barriers ? `<div class="field" style="margin-top:12px"><strong>Medication Barriers:</strong></div><div class="notes">${s.medication_barriers}</div>` : ""}
<div class="field" style="margin-top:12px"><strong>Psychiatric History:</strong></div><div class="notes">${s.psychiatric_history || "Not provided"}</div>
${s.previous_treatment_programs ? `<div class="field" style="margin-top:12px"><strong>Previous Treatment:</strong></div><div class="notes">${s.previous_treatment_programs}</div>` : ""}
<div class="grid" style="margin-top:12px">
<div class="field"><strong>TBI History:</strong> ${formatLabel(s.tbi_history)}</div>
${s.tbi_details ? `<div class="field"><strong>TBI Details:</strong> ${s.tbi_details}</div>` : ""}
<div class="field"><strong>IDD Status:</strong> ${formatLabel(s.idd_status)}</div>
${s.idd_details ? `<div class="field"><strong>IDD Details:</strong> ${s.idd_details}</div>` : ""}
</div>
${sn("clinical")}
<h2>Substance Use</h2>
<div class="grid">
<div class="field"><strong>Pattern:</strong> ${formatLabel(s.substance_use_pattern)}</div>
${s.substance_use_current ? `<div class="field"><strong>Current Use:</strong> ${s.substance_use_current}</div>` : ""}
<div class="field"><strong>Detox Required:</strong> ${formatLabel(s.detox_required)}</div>
${s.detox_details ? `<div class="field"><strong>Detox Details:</strong> ${s.detox_details}</div>` : ""}
</div>
<div class="field" style="margin-top:12px"><strong>Substance Use History:</strong></div><div class="notes">${s.substance_use_history || "Not provided"}</div>
${sn("substance")}
<h2>Medical / Somatic</h2>
<div class="field"><strong>Medical Conditions:</strong></div><div class="notes">${s.medical_conditions || "Not provided"}</div>
<div class="grid" style="margin-top:12px">
<div class="field"><strong>Controlled by Meds:</strong> ${formatLabel(s.medical_conditions_controlled)}</div>
<div class="field"><strong>Mobility:</strong> ${formatLabel(s.mobility_needs)}</div>
<div class="field"><strong>ADL Support:</strong> ${s.adl_support_needed ? "Yes" : "No"}</div>
<div class="field"><strong>Med Allergies:</strong> ${s.medication_allergies || "\u2014"}</div>
</div>
${s.medications_non_psychiatric ? `<div class="field" style="margin-top:12px"><strong>Non-Psych Medications:</strong></div><div class="notes">${s.medications_non_psychiatric}</div>` : ""}
${s.acute_medical_needs ? `<div class="field" style="margin-top:12px"><strong>Acute Medical Needs:</strong></div><div class="notes">${s.acute_medical_needs}</div>` : ""}
${sn("medical")}
<h2>Insurance / Benefits</h2>
<div class="grid">
<div class="field"><strong>Medicaid Status:</strong> ${formatLabel(s.medicaid_status)}</div>
<div class="field"><strong>Medicaid #:</strong> ${s.medicaid_number || s.medicaid_id || "\u2014"}</div>
<div class="field"><strong>Medicare Status:</strong> ${formatLabel(s.medicare_status)}</div>
<div class="field"><strong>Medicare #:</strong> ${s.medicare_number || "\u2014"}</div>
<div class="field"><strong>Private Insurance:</strong> ${s.has_private_insurance ? "Yes" : "No"}</div>
${s.private_insurance_details ? `<div class="field"><strong>Private Ins Details:</strong> ${s.private_insurance_details}</div>` : ""}
<div class="field"><strong>SSI/SSDI:</strong> ${formatLabel(s.ssdi_status)}</div>
${s.benefits_notes ? `<div class="field"><strong>Benefits Notes:</strong> ${s.benefits_notes}</div>` : ""}
</div>
${sn("insurance")}
<h2>Urgency</h2>
<div class="grid">
<div class="field"><strong>Expedited:</strong> ${expeditedUrgentColumnLabel(s.urgent_placement, s.urgency_level) || "\u2014"}</div>
${s.urgent_placement && s.urgency_level ? `<div class="field"><strong>Placement timing:</strong> ${formatLabel(s.urgency_level, URGENCY_LABELS)}</div>` : ""}
${s.urgency_reason ? `<div class="field"><strong>Urgency Reason:</strong> ${s.urgency_reason}</div>` : ""}
<div class="field"><strong>Referral Channel:</strong> ${formatLabel(s.referral_source_channel)}</div>
</div>
${s.additional_notes ? `<h2>Additional Notes</h2><div class="notes">${s.additional_notes}</div>` : ""}
${sn("urgency")}
${sn("documents")}
${sn("inventory")}
${sn("other")}
</body></html>`)
    w.document.close()
    setTimeout(() => w.print(), 500)
}

const exportSubmissionText = (s: ReferralSubmission, assignee?: AdmissionsStaffProfile | null) => {
    const assigneeLines =
        !s.assigned_to_user_id
            ? ([] as string[])
            : assignee && (assignee.display_name || assignee.title || assignee.contact_email || assignee.phone)
                ? [
                    "ADMISSIONS ASSIGNEE (published contact)",
                    "--------------------------------------",
                    `Name: ${assignee.display_name || "\u2014"}`,
                    `Title: ${assignee.title || "\u2014"}`,
                    `Email: ${assignee.contact_email || "\u2014"}`,
                    `Phone: ${formatPhone(assignee.phone || "")}`,
                    "",
                ]
                : [
                    "ADMISSIONS ASSIGNEE",
                    "-------------------",
                    "Assigned — no published profile on file yet (complete My profile on the dashboard).",
                    "",
                ]
    const lines = [
        "REFERRAL SUMMARY", "================",
        `Admin Ref: ${s.admin_ref_id || "\u2014"}`, `ID: ${s.id}`, `Referral Code: ${s.referral_code || "\u2014"}`,
        `Submitted: ${formatDate(s.created_at)}`, `Status: ${formatLabel(s.status)}`, "",
        "CLIENT INFORMATION", "------------------",
        `Name: ${s.client_first_name} ${s.client_middle_name || ""} ${s.client_last_name}`,
        `Aliases: ${s.client_preferred_name || "\u2014"}`,
        `DOB: ${formatDate(s.client_dob)}`, `Gender: ${formatLabel(s.client_gender, GENDER_LABELS)}`,
        `Sex at Birth: ${formatLabel(s.client_sex_at_birth)}`, `Pronouns: ${formatLabel(s.client_pronouns)}`,
        `SSN: ${maskSSN(s.client_ssn)}`, `Primary Language: ${s.client_primary_language || "\u2014"}`,
        `English Proficiency: ${formatLabel(s.client_english_proficiency)}`,
        `Interpreter Needed: ${s.interpreter_needed ? "Yes" : "No"}`,
        `Ethnicity: ${formatLabel(s.client_ethnicity)}`, `Marital Status: ${formatLabel(s.client_marital_status)}`,
        `Client Phone: ${formatPhone(s.client_phone)}`, `Client Email: ${s.client_email || "\u2014"}`,
        `Consents to Referral: ${formatLabel(s.client_consents_to_referral)}`, "",
        "REFERRAL SOURCE", "---------------",
        `Name: ${s.referral_source_name}`, `Type: ${formatLabel(s.referral_source_type, SOURCE_TYPE_LABELS)}`,
        `Organization: ${s.referral_source_organization || "\u2014"}`, `Title: ${s.referral_source_title || "\u2014"}`,
        `Email: ${s.referral_source_email}`, `Phone: ${formatPhone(s.referral_source_phone)}`,
        `Can Provide Collateral: ${formatLabel(s.can_provide_collateral)}`,
        `Previous Referral: ${formatLabel(s.previous_monarch_referral)}`,
        `Expedited: ${expeditedUrgentColumnLabel(s.urgent_placement, s.urgency_level) || "\u2014"}`,
        ...(s.urgent_placement && s.urgency_level ? [`Placement timing: ${formatLabel(s.urgency_level, URGENCY_LABELS)}`] : []),
        "",
        ...assigneeLines,
        "CONTACTS", "--------",
        `Emergency: ${s.emergency_contact_name || "\u2014"} (${s.emergency_contact_relationship || "\u2014"}) ${formatPhone(s.emergency_contact_phone)}`,
        `EC Can Provide Info: ${s.emergency_contact_can_provide_info ? "Yes" : "No"}`,
        ...(Array.isArray(s.additional_contacts) ? s.additional_contacts.map((c: any, i: number) =>
            `Contact ${i+1}: ${c.name || ""} - ${c.organization || ""} - ${c.role || ""} - ${c.phone_email || ""}`) : []), "",
        "LEGAL / COURT", "-------------",
        `Case #: ${s.case_number || "\u2014"}`, `Court: ${s.court_jurisdiction || "\u2014"}`,
        `Judge: ${s.judge_name || "\u2014"}`, `Courtroom: ${s.courtroom || "\u2014"}`,
        `Attorney: ${s.attorney_name || "\u2014"}`, `Attorney Phone: ${formatPhone(s.attorney_phone)}`,
        `Attorney Email: ${s.attorney_email || "\u2014"}`,
        `Charges: ${s.charges || "\u2014"}`,
        `Competency Status: ${formatLabel(s.competency_status, COMPETENCY_STATUS_LABELS)}`,
        `Comp. Eval Date: ${formatDate(s.competency_eval_date)}`, `Evaluator: ${s.competency_evaluator || "\u2014"}`,
        `Next Court Date: ${formatDate(s.next_court_date)}`,
        `On Probation: ${s.on_probation ? "Yes" : "No"}`, ...(s.on_probation ? [`PO: ${s.probation_officer_contact || "\u2014"}`] : []),
        `On Parole: ${s.on_parole ? "Yes" : "No"}`, ...(s.on_parole ? [`Parole: ${s.parole_officer_contact || "\u2014"}`] : []),
        `Active Warrants: ${formatLabel(s.active_warrants)}`, `Bond Holds: ${formatLabel(s.has_bond_holds)}`,
        ...(s.bond_holds_details ? [`Bond Details: ${s.bond_holds_details}`] : []),
        `PR Bond to Monarch: ${formatLabel(s.pr_bond_to_monarch)}`, "",
        "LOCATION / FACILITY", "-------------------",
        `Type: ${formatLabel(s.current_location_type, LOCATION_LABELS)}`,
        `Facility: ${s.facility_name || "\u2014"}`, `Address: ${s.facility_address || "\u2014"}`,
        `Inmate ID: ${s.inmate_id || "\u2014"}`,
        `Contact: ${s.facility_contact_person || "\u2014"} ${formatPhone(s.facility_contact_phone)}`,
        `Incarcerated: ${s.currently_incarcerated ? "Yes" : "No"}`,
        ...(s.expected_release_date ? [`Expected Release: ${formatDate(s.expected_release_date)}`] : []),
        `Prior Housing: ${formatLabel(s.housing_prior)}`, `Post-Program Housing: ${formatLabel(s.housing_post_program)}`,
        ...(s.housing_notes ? [`Housing Notes: ${s.housing_notes}`] : []), "",
        "RISK ASSESSMENT", "---------------",
        `Violence Risk: ${formatLabel(s.violence_risk, RISK_TIMEFRAME_LABELS)}`,
        ...(s.violence_risk_details ? [`Violence Details: ${s.violence_risk_details}`] : []),
        `Suicide Risk: ${formatLabel(s.suicide_risk, RISK_TIMEFRAME_LABELS)}`,
        ...(s.suicide_risk_details ? [`Suicide Details: ${s.suicide_risk_details}`] : []),
        `Elopement Risk: ${formatLabel(s.elopement_risk, RISK_TIMEFRAME_LABELS)}`,
        ...(s.elopement_risk_details ? [`Elopement Details: ${s.elopement_risk_details}`] : []),
        `Arson: ${formatLabel(s.arson_history)}`, ...(s.arson_details ? [`Arson Details: ${s.arson_details}`] : []),
        `RSO: ${formatLabel(s.rso_status)}`, ...(s.rso_details ? [`RSO Details: ${s.rso_details}`] : []),
        `Medical Needs: ${s.medical_needs ? "YES" : "No"}`,
        `Safety Notes: ${s.safety_notes || "\u2014"}`, "",
        "CLINICAL / MENTAL HEALTH", "------------------------",
        `Diagnoses: ${s.current_diagnoses || "Not provided"}`,
        `Med Compliance: ${formatLabel(s.medication_compliance)}`,
        `Medications: ${formatMedications(s.current_medications)}`,
        ...(s.medication_barriers ? [`Med Barriers: ${s.medication_barriers}`] : []),
        `Psychiatric History: ${s.psychiatric_history || "Not provided"}`,
        ...(s.previous_treatment_programs ? [`Previous Treatment: ${s.previous_treatment_programs}`] : []),
        `TBI: ${formatLabel(s.tbi_history)}`, ...(s.tbi_details ? [`TBI Details: ${s.tbi_details}`] : []),
        `IDD: ${formatLabel(s.idd_status)}`, ...(s.idd_details ? [`IDD Details: ${s.idd_details}`] : []), "",
        "SUBSTANCE USE", "-------------",
        `Pattern: ${formatLabel(s.substance_use_pattern)}`,
        ...(s.substance_use_current ? [`Current Use: ${s.substance_use_current}`] : []),
        `History: ${s.substance_use_history || "Not provided"}`,
        `Detox Required: ${formatLabel(s.detox_required)}`,
        ...(s.detox_details ? [`Detox Details: ${s.detox_details}`] : []), "",
        "MEDICAL / SOMATIC", "-----------------",
        `Medical Conditions: ${s.medical_conditions || "Not provided"}`,
        `Controlled by Meds: ${formatLabel(s.medical_conditions_controlled)}`,
        ...(s.medications_non_psychiatric ? [`Non-Psych Meds: ${s.medications_non_psychiatric}`] : []),
        `Med Allergies: ${s.medication_allergies || "\u2014"}`,
        `Mobility: ${formatLabel(s.mobility_needs)}`,
        `ADL Support: ${s.adl_support_needed ? "Yes" : "No"}`,
        ...(s.adl_support_details ? [`ADL Details: ${s.adl_support_details}`] : []),
        ...(s.acute_medical_needs ? [`Acute Needs: ${s.acute_medical_needs}`] : []), "",
        "INSURANCE / BENEFITS", "--------------------",
        `Medicaid: ${formatLabel(s.medicaid_status)}`, `Medicaid #: ${s.medicaid_number || s.medicaid_id || "\u2014"}`,
        `Medicare: ${formatLabel(s.medicare_status)}`, `Medicare #: ${s.medicare_number || "\u2014"}`,
        `Private Insurance: ${s.has_private_insurance ? "Yes" : "No"}`,
        ...(s.private_insurance_details ? [`Private Ins: ${s.private_insurance_details}`] : []),
        `SSI/SSDI: ${formatLabel(s.ssdi_status)}`,
        ...(s.benefits_notes ? [`Benefits Notes: ${s.benefits_notes}`] : []), "",
        "URGENCY", "-------",
        `Expedited: ${expeditedUrgentColumnLabel(s.urgent_placement, s.urgency_level) || "\u2014"}`,
        ...(s.urgent_placement && s.urgency_level ? [`Placement timing: ${formatLabel(s.urgency_level, URGENCY_LABELS)}`] : []),
        ...(s.urgency_reason ? [`Reason: ${s.urgency_reason}`] : []),
        `Referral Channel: ${formatLabel(s.referral_source_channel)}`, "",
        "NOTES", "-----", s.additional_notes || "None",
    ]
    downloadFile(lines.join("\n"), `referral_${s.client_last_name}_${s.client_first_name}.txt`, "text/plain")
}

// ============================================================================
// BADGE / ICON COMPONENTS (playground parity — icons over text pills)
// ============================================================================

const REFERRAL_STATUS_ICON_SIZE = 18

function ReferralStatusIconWrap({ title, color, children, size = REFERRAL_STATUS_ICON_SIZE }: { title: string; color: string; children: React.ReactNode; size?: number }) {
    return (
        <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }} title={title} aria-label={title} role="img">
            <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                {children}
            </svg>
        </span>
    )
}

function ReferralStatusIcon({ status }: { status: ReferralStatus }) {
    const title = formatLabel(status)
    switch (status) {
        case "pending_review":
            return (
                <ReferralStatusIconWrap title={title} color={COLORS.primary}>
                    <path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .962 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.962 0z" />
                    <path d="M20 3v4" /><path d="M22 5h-4" /><path d="M4 17v2" /><path d="M5 18H3" />
                </ReferralStatusIconWrap>
            )
        case "under_review":
            return (
                <ReferralStatusIconWrap title={title} color={COLORS.statusReviewText}>
                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                    <path d="M14 2v6h6" />
                    <circle cx="12" cy="14" r="1.5" />
                    <path d="M12 16.5c-1.8 0-3.2-.9-4-2.2.8-1.3 2.2-2.2 4-2.2s3.2.9 4 2.2c-.8 1.3-2.2 2.2-4 2.2z" />
                </ReferralStatusIconWrap>
            )
        case "waitlisted":
            return (
                <ReferralStatusIconWrap title={title} color={COLORS.statusWaitlistText}>
                    <circle cx="12" cy="12" r="10" />
                    <line x1="10" x2="10" y1="15" y2="9" />
                    <line x1="14" x2="14" y1="15" y2="9" />
                </ReferralStatusIconWrap>
            )
        case "accepted":
            return (
                <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }} title={title} aria-label={title} role="img">
                    <svg width={REFERRAL_STATUS_ICON_SIZE} height={REFERRAL_STATUS_ICON_SIZE} viewBox="0 0 24 24" fill="none" stroke={COLORS.success} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                        <circle cx="12" cy="12" r="10" strokeWidth="2" />
                        <path d="M6.5 12.5l3.5 3.5 7.5-8" strokeWidth="2.5" />
                    </svg>
                </span>
            )
        case "declined":
            return (
                <ReferralStatusIconWrap title={title} color={COLORS.statusDeclinedText}>
                    <circle cx="12" cy="12" r="10" />
                    <path d="m4.2 4.2 15.6 15.6" />
                </ReferralStatusIconWrap>
            )
        default:
            return null
    }
}

function kanbanClientNameStyle(extra?: React.CSSProperties): React.CSSProperties {
    return {
        fontSize: 14,
        fontWeight: 600,
        color: COLORS.infoText,
        fontFamily: FONT_HEADING,
        letterSpacing: "-0.02em",
        ...extra,
    }
}

function ReferralActionsMetaIcons({
    referral,
    showStatus = true,
    showUrgency = true,
    showIndicators = true,
}: {
    referral: Pick<ReferralSubmission, "status" | "urgent_placement" | "urgency_level" | "has_unread_messages" | "uploaded_documents">
    showStatus?: boolean
    showUrgency?: boolean
    showIndicators?: boolean
}) {
    const expeditedMode = showUrgency ? expeditedPlacementDisplay(referral.urgent_placement, referral.urgency_level) : "none"
    const urgencyIcon =
        expeditedMode === "lightning_circled" ? (
            <KanbanExpeditedIcon mode="lightning_circled" />
        ) : expeditedMode === "lightning" ? (
            <KanbanExpeditedIcon mode="lightning" />
        ) : null
    const docCount = Array.isArray(referral.uploaded_documents) ? referral.uploaded_documents.length : 0
    const icons = [
        showStatus ? <ReferralStatusIcon key="status" status={referral.status as ReferralStatus} /> : null,
        urgencyIcon,
        showIndicators && docCount > 0 ? <KanbanPaperclipIcon key="attach" /> : null,
        showIndicators && referral.has_unread_messages ? <KanbanMessageIcon key="msg" /> : null,
    ].filter(Boolean)
    if (icons.length === 0) return null
    return (
        <div style={{ display: "inline-flex", flexWrap: "wrap", alignItems: "center", gap: 6 }}>
            {icons}
        </div>
    )
}

const UrgentBadge = ({ urgent }: { urgent: boolean }) => {
    if (!urgent) return null
    return <KanbanExpeditedIcon mode="lightning" />
}

const EXPEDITED_URGENT_DOT_PX = 22

/** Urgent column: A/C in tangerine dot; R as tangerine letter only (all breakpoints). */
const ExpeditedUrgentCell = ({
    urgentPlacement,
    urgencyLevel,
}: {
    urgentPlacement: boolean | undefined | null
    urgencyLevel: string | null | undefined
}) => {
    const label = expeditedUrgentColumnLabel(urgentPlacement, urgencyLevel)
    if (!label) {
        return <span style={{ fontSize: "12px", color: COLORS.ashMuted }}>{"\u2014"}</span>
    }
    const dotBase: React.CSSProperties = {
        width: EXPEDITED_URGENT_DOT_PX,
        height: EXPEDITED_URGENT_DOT_PX,
        borderRadius: "50%",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "11px",
        fontWeight: 700,
        fontFamily: FONT,
        lineHeight: 1,
        flexShrink: 0,
    }
    const title =
        label === "ASAP"
            ? "ASAP — Soonest available"
            : label === "Conditional"
              ? "Conditional timeline"
              : "Expedited placement requested"
    if (label === "ASAP") {
        return (
            <span title={title} style={{ ...dotBase, background: COLORS.tangerine, color: COLORS.white }} aria-label={title}>
                A
            </span>
        )
    }
    if (label === "Conditional") {
        return (
            <span title={title} style={{ ...dotBase, background: COLORS.tangerine, color: COLORS.ash }} aria-label={title}>
                C
            </span>
        )
    }
    return (
        <span title={title} style={{ fontSize: "13px", fontWeight: 700, color: COLORS.tangerine, fontFamily: FONT }} aria-label={title}>
            R
        </span>
    )
}

const TypeBadge = ({ type }: { type: string }) => (
    <span style={TYPE_BADGE_STYLE}>
        {SOURCE_TYPE_LABELS[type] || formatLabel(type)}
    </span>
)

const StatusBadge = ({ status }: { status: string }) => (
    <ReferralStatusIcon status={(status || "pending_review") as ReferralStatus} />
)

const RiskIndicator = ({ label, active, value }: { label: string; active?: boolean; value?: string }) => {
    // Support both boolean (medical_needs) and text enum (risk timeframes)
    const isActive = active !== undefined ? active : (value ? value !== "no_history" && value !== "" : false)
    const displayValue = value ? formatLabel(value, RISK_TIMEFRAME_LABELS) : (isActive ? "YES" : "NO")
    return (
        <div style={{
            padding: "14px", borderRadius: RADIUS.section, textAlign: "center",
            background: isActive ? COLORS.tangerineLight : COLORS.coconut,
            border: isActive ? `2px solid ${COLORS.tangerine}` : `1px solid ${COLORS.ashSubtle}`,
        }}>
            <div style={{
                fontSize: "11px", fontWeight: 600, fontFamily: FONT, textTransform: "uppercase",
                letterSpacing: "0.04em", marginBottom: "4px",
                color: isActive ? COLORS.redText : COLORS.ashMuted,
            }}>
                {label}
            </div>
            <div style={{
                fontSize: value ? "12px" : "16px", fontWeight: 700, fontFamily: FONT,
                color: isActive ? COLORS.redText : COLORS.ashMuted,
            }}>
                {displayValue}
            </div>
        </div>
    )
}

const ActionButton = ({ onClick, title, children, compact }: { onClick: () => void; title: string; children: React.ReactNode; compact?: boolean }) => (
    <button onClick={onClick} title={title} style={{
        ...pillBtnBase, background: COLORS.coconut, color: COLORS.ash,
        padding: compact ? "4px 8px" : "6px 12px",
        fontSize: compact ? "12px" : "13px",
        border: `1px solid ${COLORS.ashSubtle}`,
        flexShrink: 0,
    }}>
        {children}
    </button>
)

// ============================================================================
// HEADER CELL
// ============================================================================

const HeaderCell = ({ column, label, sortColumn, sortDirection, onSort, sortable = true, title, compact }: {
    column: string; label: string; sortColumn: string; sortDirection: "asc" | "desc"
    onSort: (col: string) => void; sortable?: boolean; title?: string; compact?: boolean
}) => (
    <div style={{
        ...TABLE_COLUMN_HEADER_STYLE,
        padding: compact ? "10px 6px" : "14px 12px",
        cursor: sortable ? "pointer" : "default",
        display: "flex",
        alignItems: "center",
        gap: "4px",
        userSelect: "none",
        overflow: "hidden",
        textOverflow: "ellipsis",
        whiteSpace: "nowrap" as const,
    }} title={title} onClick={() => sortable && onSort(column)}>
        {label}
        {sortable && sortColumn === column && (
            <span style={{ color: COLORS.moonstone, fontSize: "12px", fontWeight: 700 }}>
                {sortDirection === "asc" ? "\u2191" : "\u2193"}
            </span>
        )}
    </div>
)

// ============================================================================
// STAFF ACCESS + ADMINISTRATION (step 5 — production wiring)
// ============================================================================

const StaffAccessDeniedView = ({
    email,
    reason,
}: {
    email: string
    reason: "blocked" | "not_approved"
}) => {
    const copy =
        reason === "blocked"
            ? {
                  title: "Dashboard access removed",
                  body: "Your account has been blocked from the admissions dashboard. Contact your admissions admin if you believe this is an error.",
              }
            : {
                  title: "Dashboard access not approved",
                  body: `You signed in with a @monarchcompetency.com account, but admissions has not added you to the staff allowlist yet. Contact your admissions admin to request access.`,
              }

    return (
        <div
            style={{
                flex: 1,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                padding: "32px",
                minHeight: 0,
            }}
        >
            <div
                style={{
                    maxWidth: "480px",
                    width: "100%",
                    padding: "28px 32px",
                    background: COLORS.white,
                    border: `1px solid ${COLORS.ashSubtle}`,
                    borderRadius: RADIUS.section,
                    fontFamily: FONT,
                    textAlign: "center",
                }}
            >
                <h1 style={{ margin: "0 0 12px", fontSize: "22px", fontWeight: 700, color: COLORS.ash }}>{copy.title}</h1>
                <p style={{ margin: "0 0 20px", fontSize: "14px", color: COLORS.ashMuted, lineHeight: 1.55 }}>{copy.body}</p>
                <div
                    style={{
                        fontSize: "12px",
                        color: COLORS.ashMuted,
                        padding: "12px 14px",
                        background: COLORS.coconut25,
                        borderRadius: RADIUS.small,
                        textAlign: "left",
                        lineHeight: 1.5,
                    }}
                >
                    <div>
                        <strong style={{ color: COLORS.ash }}>Signed in as:</strong> {email}
                    </div>
                    <div>
                        <strong style={{ color: COLORS.ash }}>Program:</strong> {ACTIVE_MONARCH_PROGRAM.displayName}
                    </div>
                </div>
            </div>
        </div>
    )
}

const StaffAdministrationPanel = ({
    programId,
    actorEmail,
    isSuperAdmin,
    onError,
}: {
    programId: string
    actorEmail: string
    isSuperAdmin: boolean
    onError: (message: string) => void
}) => {
    const [memberships, setMemberships] = useState<StaffProgramMembershipRow[]>([])
    const [blockedSources, setBlockedSources] = useState<BlockedPortalSourceRow[]>([])
    const [loading, setLoading] = useState(true)
    const [addEmail, setAddEmail] = useState("")
    const [blockEmail, setBlockEmail] = useState("")
    const [busy, setBusy] = useState(false)

    const loadAdminData = useCallback(async () => {
        setLoading(true)
        try {
            const [memRes, blockRes] = await Promise.all([
                supabase.rpc("list_staff_program_memberships_admin", { p_program_id: programId }),
                supabase.rpc("list_staff_blocked_portal_sources"),
            ])
            if (memRes.error) throw memRes.error
            if (blockRes.error) throw blockRes.error
            setMemberships((memRes.data || []) as StaffProgramMembershipRow[])
            setBlockedSources((blockRes.data || []) as BlockedPortalSourceRow[])
        } catch (err: any) {
            console.error("[Dashboard] Administration load failed:", err)
            onError(err?.message || "Failed to load administration data")
        } finally {
            setLoading(false)
        }
    }, [programId, onError])

    useEffect(() => {
        void loadAdminData()
    }, [loadAdminData])

    const handleAddStaff = async () => {
        const email = addEmail.trim().toLowerCase()
        if (!email) return
        setBusy(true)
        try {
            const { data, error } = await supabase.rpc("upsert_staff_program_membership", {
                p_email: email,
                p_program_id: programId,
                p_role: "user",
            })
            if (error) throw error
            const result = data as { ok?: boolean; message?: string; code?: string }
            if (!result?.ok) {
                window.alert(result?.message || "Could not add staff member.")
                return
            }
            setAddEmail("")
            await loadAdminData()
            window.alert(`Staff access granted for ${email}. They can use the dashboard on next sign-in.`)
        } catch (err: any) {
            onError(err?.message || "Failed to add staff")
        } finally {
            setBusy(false)
        }
    }

    const handleSetStatus = async (row: StaffProgramMembershipRow, status: "active" | "blocked") => {
        setBusy(true)
        try {
            const { error } = await supabase.rpc("set_staff_program_membership_status", {
                p_membership_id: row.id,
                p_status: status,
            })
            if (error) throw error
            await loadAdminData()
        } catch (err: any) {
            onError(err?.message || "Failed to update staff status")
        } finally {
            setBusy(false)
        }
    }

    const handleSetRole = async (row: StaffProgramMembershipRow, role: "user" | "admin") => {
        setBusy(true)
        try {
            const { error } = await supabase.rpc("set_staff_program_membership_role", {
                p_membership_id: row.id,
                p_role: role,
            })
            if (error) throw error
            await loadAdminData()
        } catch (err: any) {
            onError(err?.message || "Failed to update role")
        } finally {
            setBusy(false)
        }
    }

    const handleBlockPortal = async () => {
        const email = blockEmail.trim().toLowerCase()
        if (!email) return
        setBusy(true)
        try {
            const { data, error } = await supabase.rpc("staff_deactivate_referral_source_profile", { p_email: email })
            if (error) throw error
            const result = data as { ok?: boolean; message?: string }
            if (!result?.ok) {
                window.alert(result?.message || "Could not block portal source.")
                return
            }
            setBlockEmail("")
            await loadAdminData()
            window.alert(`Portal access blocked for ${email}. Archive related referrals separately in Cases.`)
        } catch (err: any) {
            onError(err?.message || "Failed to block portal source")
        } finally {
            setBusy(false)
        }
    }

    const handleUnblockPortal = async (userId: string) => {
        setBusy(true)
        try {
            const { error } = await supabase.rpc("staff_reactivate_referral_source_profile", { p_user_id: userId })
            if (error) throw error
            await loadAdminData()
        } catch (err: any) {
            onError(err?.message || "Failed to unblock portal source")
        } finally {
            setBusy(false)
        }
    }

    if (loading) {
        return (
            <div style={{ padding: "40px", textAlign: "center", color: COLORS.ashMuted, fontFamily: FONT, fontSize: "14px" }}>
                Loading administration…
            </div>
        )
    }

    return (
        <div style={{ flex: 1, minHeight: 0, overflow: "auto", paddingBottom: "24px" }}>
            <div style={{ marginBottom: "20px" }}>
                <h2 style={{ margin: 0, fontSize: "20px", fontWeight: 700, color: COLORS.ash, fontFamily: FONT }}>Administration</h2>
                <p style={{ margin: "6px 0 0", fontSize: "13px", color: COLORS.ashMuted, lineHeight: 1.55, maxWidth: "640px" }}>
                    Manage admissions dashboard access for {ACTIVE_MONARCH_PROGRAM.displayName}. Admissions admins add or block staff.
                    {isSuperAdmin ? " Platform super admins may assign the admissions admin role." : " Only platform super admins may assign admissions admin."}
                </p>
            </div>

            <section style={{ marginBottom: "28px", padding: "20px", background: COLORS.white, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.section }}>
                <h3 style={{ margin: "0 0 12px", fontSize: "16px", fontWeight: 700, color: COLORS.ash }}>Staff allowlist</h3>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginBottom: "16px", alignItems: "flex-end" }}>
                    <label style={{ display: "flex", flexDirection: "column", gap: "4px", fontSize: "12px", fontWeight: 600 }}>
                        Email
                        <input
                            value={addEmail}
                            onChange={(e) => setAddEmail(e.target.value)}
                            placeholder="name@monarchcompetency.com"
                            style={{ padding: "8px 12px", fontSize: "13px", fontFamily: FONT, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.small, minWidth: "240px" }}
                        />
                    </label>
                    <button type="button" disabled={busy} onClick={() => void handleAddStaff()} style={{ ...pillBtnBase, padding: "8px 14px", background: COLORS.moonstone, color: COLORS.white }}>
                        Add staff
                    </button>
                </div>
                <p style={{ margin: "0 0 12px", fontSize: "12px", color: COLORS.ashMuted }}>
                    New hires must sign in once at {ACTIVE_MONARCH_PROGRAM.staffLoginPath} before their email can be added.
                </p>
                <div style={{ overflowX: "auto" }}>
                    <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13px", fontFamily: FONT }}>
                        <thead>
                            <tr style={{ borderBottom: `1px solid ${COLORS.ashSubtle}`, textAlign: "left" }}>
                                <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Name</th>
                                <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Email</th>
                                <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Role</th>
                                <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Status</th>
                                <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {memberships.map((row) => (
                                <tr key={row.id} style={{ borderBottom: `1px solid ${COLORS.coconut25}` }}>
                                    <td style={ADMIN_TABLE_BODY_CELL_STYLE}>{row.display_name || "—"}</td>
                                    <td style={ADMIN_TABLE_BODY_CELL_STYLE}>{row.email}</td>
                                    <td style={{ padding: "12px 8px" }}>
                                        {isSuperAdmin ? (
                                            <select
                                                value={row.role}
                                                disabled={busy}
                                                onChange={(e) => void handleSetRole(row, e.target.value as "user" | "admin")}
                                                style={{ padding: "6px 10px", fontSize: "12px", fontFamily: FONT, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.small }}
                                            >
                                                <option value="user">Admissions staff</option>
                                                <option value="admin">Admissions admin</option>
                                            </select>
                                        ) : (
                                            row.role === "admin" ? "Admissions admin" : "Admissions staff"
                                        )}
                                    </td>
                                    <td style={ADMIN_TABLE_BODY_CELL_STYLE}>{row.status === "active" ? "Active" : "Blocked"}</td>
                                    <td style={{ padding: "12px 8px" }}>
                                        {row.status === "active" ? (
                                            <button type="button" disabled={busy} onClick={() => void handleSetStatus(row, "blocked")} style={{ ...pillBtnBase, padding: "6px 10px", fontSize: "12px", background: COLORS.coconut25, color: COLORS.ash }}>
                                                Block
                                            </button>
                                        ) : (
                                            <button type="button" disabled={busy} onClick={() => void handleSetStatus(row, "active")} style={{ ...pillBtnBase, padding: "6px 10px", fontSize: "12px", background: COLORS.moonstone, color: COLORS.white }}>
                                                Restore
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </section>

            <section style={{ padding: "20px", background: COLORS.white, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.section }}>
                <h3 style={{ margin: "0 0 12px", fontSize: "16px", fontWeight: 700, color: COLORS.ash }}>Blocked referral sources</h3>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginBottom: "16px", alignItems: "flex-end" }}>
                    <label style={{ display: "flex", flexDirection: "column", gap: "4px", fontSize: "12px", fontWeight: 600 }}>
                        Portal email
                        <input
                            value={blockEmail}
                            onChange={(e) => setBlockEmail(e.target.value)}
                            placeholder="source@example.com"
                            style={{ padding: "8px 12px", fontSize: "13px", fontFamily: FONT, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.small, minWidth: "220px" }}
                        />
                    </label>
                    <button type="button" disabled={busy} onClick={() => void handleBlockPortal()} style={{ ...pillBtnBase, padding: "8px 14px", background: COLORS.tangerine, color: COLORS.white }}>
                        Block portal access
                    </button>
                </div>
                {blockedSources.length > 0 ? (
                    <div style={{ overflowX: "auto" }}>
                        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13px", fontFamily: FONT }}>
                            <thead>
                                <tr style={{ borderBottom: `1px solid ${COLORS.ashSubtle}`, textAlign: "left" }}>
                                    <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Email</th>
                                    <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }}>Blocked</th>
                                    <th style={{ ...TABLE_COLUMN_HEADER_STYLE, padding: "10px 8px" }} />
                                </tr>
                            </thead>
                            <tbody>
                                {blockedSources.map((row) => (
                                    <tr key={row.user_id} style={{ borderBottom: `1px solid ${COLORS.coconut25}` }}>
                                        <td style={ADMIN_TABLE_BODY_CELL_STYLE}>{row.email}</td>
                                        <td style={{ padding: "12px 8px", fontSize: "12px", color: COLORS.ashMuted }}>{formatDate(row.profile_deactivated_at)}</td>
                                        <td style={{ padding: "12px 8px" }}>
                                            <button type="button" disabled={busy} onClick={() => void handleUnblockPortal(row.user_id)} style={{ ...pillBtnBase, padding: "6px 10px", fontSize: "12px", background: COLORS.coconut25, color: COLORS.ash }}>
                                                Unblock
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <p style={{ margin: 0, fontSize: "13px", color: COLORS.ashMuted }}>No blocked portal sources.</p>
                )}
                <p style={{ margin: "12px 0 0", fontSize: "12px", color: COLORS.ashMuted }}>Signed in as {actorEmail}</p>
            </section>
        </div>
    )
}

// ============================================================================
// ACTIVITY FEED (program-wide timeline)
// ============================================================================

interface ActivityFeedLogRow {
    id: string
    referral_id: string
    activity_type: string
    actor_email: string | null
    details: Record<string, unknown>
    created_at: string
}

const ACTIVITY_FEED_TYPE_FILTER_OPTIONS: { value: ActivityFeedTypeFilter; label: string }[] = [
    { value: "all", label: "All types" },
    { value: "referral_submitted", label: "Submitted" },
    { value: "status_change", label: "Status" },
    { value: "message", label: "Messages" },
    { value: "assignment_changed", label: "Assignment" },
    { value: "section_note", label: "Notes" },
    { value: "documents", label: "Documents & ROI" },
]

const ActivityFeedPanel = ({
    submissions,
    programNamesById,
    currentUserId,
    onOpenReferral,
}: {
    submissions: ReferralSubmission[]
    programNamesById: Record<string, string>
    currentUserId: string | null
    onOpenReferral: (submission: ReferralSubmission) => void
}) => {
    const [scope, setScope] = useState<"all" | "mine">("all")
    const [typeFilter, setTypeFilter] = useState<ActivityFeedTypeFilter>("all")
    const [rows, setRows] = useState<ActivityFeedLogRow[]>([])
    const [loading, setLoading] = useState(true)
    const [fetchError, setFetchError] = useState<string | null>(null)

    const submissionsById = useMemo(() => new Map(submissions.map((s) => [s.id, s])), [submissions])

    useEffect(() => {
        let cancelled = false
        setLoading(true)
        setFetchError(null)
        supabase
            .from("referral_activity_log")
            .select("id, referral_id, activity_type, actor_email, details, created_at")
            .neq("activity_type", "referral_viewed")
            .order("created_at", { ascending: false })
            .limit(250)
            .then(({ data, error }) => {
                if (cancelled) return
                if (error) {
                    setFetchError(error.message || "Could not load activity feed")
                    setRows([])
                } else {
                    setRows((data as ActivityFeedLogRow[]) || [])
                }
                setLoading(false)
            })
        return () => {
            cancelled = true
        }
    }, [])

    const filteredRows = useMemo(() => {
        return rows.filter((entry) => {
            const submission = submissionsById.get(entry.referral_id)
            if (!submission) return false
            if (scope === "mine" && submission.assigned_to_user_id !== currentUserId) return false
            if (!matchesActivityFeedTypeFilter(entry.activity_type, typeFilter)) return false
            return true
        })
    }, [rows, submissionsById, scope, typeFilter, currentUserId])

    const grouped = useMemo(() => {
        const byDay = new Map<string, ActivityFeedLogRow[]>()
        for (const entry of filteredRows) {
            const day = activityDayKey(entry.created_at)
            if (!byDay.has(day)) byDay.set(day, [])
            byDay.get(day)!.push(entry)
        }
        return Array.from(byDay.entries())
            .sort(([a], [b]) => b.localeCompare(a))
            .map(([day, items]) => ({ day, items }))
    }, [filteredRows])

    const openEntry = (entry: ActivityFeedLogRow) => {
        const submission = submissionsById.get(entry.referral_id)
        if (submission) onOpenReferral(submission)
    }

    return (
        <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flexShrink: 0, marginBottom: 12 }}>
                <h2 style={{ margin: 0, fontSize: "22px", fontWeight: 700, color: COLORS.ash, fontFamily: FONT }}>
                    Activity Feed
                </h2>
                <p style={{ margin: "6px 0 0", fontSize: "13px", color: COLORS.ashMuted, lineHeight: 1.5, fontFamily: FONT }}>
                    Program-wide timeline of substantive referral updates — status, messages, assignment, documents, and ROI.
                    View-only opens are not shown here.
                </p>
            </div>

            <div
                style={{
                    display: "flex",
                    flexWrap: "wrap",
                    alignItems: "center",
                    gap: 8,
                    marginBottom: 16,
                    flexShrink: 0,
                }}
            >
                <div style={{ display: "flex", gap: 6 }}>
                    {(
                        [
                            { key: "all" as const, label: "All activity" },
                            { key: "mine" as const, label: "My assignments" },
                        ] as const
                    ).map((item) => (
                        <button
                            key={item.key}
                            type="button"
                            onClick={() => setScope(item.key)}
                            style={{
                                ...pillBtnBase,
                                padding: "8px 14px",
                                fontSize: "13px",
                                background: scope === item.key ? COLORS.ash : COLORS.white,
                                color: scope === item.key ? COLORS.white : COLORS.ash,
                                border: `1px solid ${scope === item.key ? COLORS.ash : COLORS.ashSubtle}`,
                            }}
                        >
                            {item.label}
                        </button>
                    ))}
                </div>

                <select
                    value={typeFilter}
                    onChange={(e) => setTypeFilter(e.target.value as ActivityFeedTypeFilter)}
                    style={{
                        padding: "8px 12px",
                        fontSize: "13px",
                        fontFamily: FONT,
                        border: `1px solid ${COLORS.ashSubtle}`,
                        borderRadius: RADIUS.small,
                        background: COLORS.white,
                        color: COLORS.ash,
                        cursor: "pointer",
                    }}
                    aria-label="Filter by event type"
                >
                    {ACTIVITY_FEED_TYPE_FILTER_OPTIONS.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                            {opt.label}
                        </option>
                    ))}
                </select>

                <span style={{ fontSize: "12px", color: COLORS.ashMuted, marginLeft: "auto", fontFamily: FONT }}>
                    {filteredRows.length} event{filteredRows.length === 1 ? "" : "s"}
                </span>
            </div>

            <div style={{ flex: 1, minHeight: 0, overflowY: "auto", paddingRight: 4 }}>
                {fetchError ? (
                    <p style={{ margin: 0, fontSize: "14px", color: COLORS.redText, fontFamily: FONT, padding: 24, textAlign: "center" }}>
                        {fetchError}
                    </p>
                ) : loading ? (
                    <p style={{ margin: 0, fontSize: "14px", color: COLORS.ashMuted, fontFamily: FONT, padding: 24, textAlign: "center" }}>
                        Loading activity…
                    </p>
                ) : filteredRows.length === 0 ? (
                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            minHeight: 200,
                            color: COLORS.ashMuted,
                            fontSize: "14px",
                            textAlign: "center",
                            padding: 24,
                            fontFamily: FONT,
                        }}
                    >
                        No activity matches these filters.
                    </div>
                ) : (
                    grouped.map(({ day, items }) => (
                        <section key={day} style={{ marginBottom: 20 }}>
                            <div
                                style={{
                                    fontSize: "11px",
                                    fontWeight: 700,
                                    letterSpacing: "0.06em",
                                    textTransform: "uppercase",
                                    color: COLORS.ashMuted,
                                    marginBottom: 8,
                                    fontFamily: FONT,
                                }}
                            >
                                {formatDate(day)}
                            </div>
                            <div
                                style={{
                                    border: `1px solid ${COLORS.ashSubtle}`,
                                    borderRadius: RADIUS.small,
                                    background: COLORS.white,
                                    overflow: "hidden",
                                }}
                            >
                                {items.map((entry, index) => {
                                    const submission = submissionsById.get(entry.referral_id)!
                                    const badge = activityTypeBadgeColors(entry.activity_type)
                                    const clientName = `${submission.client_first_name || ""} ${submission.client_last_name || ""}`.trim() || "Unknown client"
                                    return (
                                        <button
                                            key={entry.id}
                                            type="button"
                                            onClick={() => openEntry(entry)}
                                            style={{
                                                width: "100%",
                                                display: "grid",
                                                gridTemplateColumns: "88px 1fr auto",
                                                gap: 12,
                                                alignItems: "start",
                                                padding: "12px 14px",
                                                border: "none",
                                                borderBottom:
                                                    index < items.length - 1 ? `1px solid ${COLORS.ashSubtle}` : undefined,
                                                background: "transparent",
                                                cursor: "pointer",
                                                textAlign: "left",
                                                fontFamily: FONT,
                                            }}
                                        >
                                            <span
                                                style={{
                                                    fontSize: "11px",
                                                    fontWeight: 700,
                                                    letterSpacing: "0.04em",
                                                    color: badge.text,
                                                    background: badge.bg,
                                                    padding: "4px 8px",
                                                    borderRadius: RADIUS.small,
                                                    justifySelf: "start",
                                                }}
                                            >
                                                {activityTypeBadgeLabel(entry.activity_type)}
                                            </span>
                                            <span style={{ minWidth: 0 }}>
                                                <span
                                                    style={{
                                                        display: "block",
                                                        fontSize: "14px",
                                                        fontWeight: 600,
                                                        color: COLORS.ash,
                                                    }}
                                                >
                                                    {clientName}{" "}
                                                    <span style={{ fontWeight: 500, color: COLORS.ashMuted }}>
                                                        {referralFeedLabel(submission)}
                                                    </span>
                                                </span>
                                                <span
                                                    style={{
                                                        display: "block",
                                                        marginTop: 4,
                                                        fontSize: "13px",
                                                        color: COLORS.ashMuted,
                                                        lineHeight: 1.45,
                                                    }}
                                                >
                                                    {activityLogEntryLabel(entry)}
                                                </span>
                                                <span style={{ display: "block", marginTop: 4, fontSize: "12px", color: COLORS.ashMuted }}>
                                                    {entry.actor_email || "—"} · {submissionProgramDisplay(submission, programNamesById)}
                                                </span>
                                            </span>
                                            <span
                                                style={{
                                                    fontSize: "12px",
                                                    color: COLORS.ashMuted,
                                                    whiteSpace: "nowrap",
                                                    paddingTop: 2,
                                                }}
                                            >
                                                {formatActivityTime(entry.created_at)}
                                            </span>
                                        </button>
                                    )
                                })}
                            </div>
                        </section>
                    ))
                )}
            </div>
        </div>
    )
}

// ============================================================================
// ARCHIVE (dedicated tab — recover archived submissions & inquiries)
// ============================================================================

type ArchiveInnerTab = "submissions" | "inquiries"

const StaffArchivePanel = ({
    archivedSubmissions,
    archivedInquiries,
    programNamesById,
    staffAssigneeByUserId,
    currentUserId,
    onOpenSubmission,
    onOpenInquiry,
    onRequestRecover,
    onStatusUpdate,
    updatingStatus,
}: {
    archivedSubmissions: ReferralSubmission[]
    archivedInquiries: ReferralInquiry[]
    programNamesById: Record<string, string>
    staffAssigneeByUserId: Record<string, AdmissionsStaffProfile | undefined>
    currentUserId: string | null
    onOpenSubmission: (submission: ReferralSubmission) => void
    onOpenInquiry: (inquiry: ReferralInquiry) => void
    onRequestRecover: (ids: string[], table: "referral_submissions" | "referral_inquiries") => void
    onStatusUpdate: (id: string, status: ReferralStatus, table: string) => void
    updatingStatus: string | null
}) => {
    const { isNarrow, isCompactTable } = useMonarchViewport()
    const [innerTab, setInnerTab] = useState<ArchiveInnerTab>("submissions")
    const [searchQuery, setSearchQuery] = useState("")
    const [subFilters, setSubFilters] = useState({ sourceType: "all", status: "all", urgent: "all", assigned: "all" })
    const [inqFilters, setInqFilters] = useState({ inquiryType: "all", status: "all" })
    const [submissionSort, setSubmissionSort] = useState<SortConfig>({ column: "archived_at", direction: "desc" })
    const [inquirySort, setInquirySort] = useState<SortConfig>({ column: "archived_at", direction: "desc" })
    const [selectedSubs, setSelectedSubs] = useState<Set<string>>(() => new Set())
    const [selectedInqs, setSelectedInqs] = useState<Set<string>>(() => new Set())

    const filteredSubmissions = useMemo(() => {
        let f = archivedSubmissions
        if (searchQuery) {
            const q = searchQuery.toLowerCase()
            f = f.filter((s) =>
                (s.client_first_name || "").toLowerCase().includes(q) ||
                (s.client_last_name || "").toLowerCase().includes(q) ||
                (s.referral_source_name || "").toLowerCase().includes(q) ||
                (s.referral_code || "").toLowerCase().includes(q) ||
                (s.admin_ref_id || "").toLowerCase().includes(q) ||
                submissionProgramDisplay(s, programNamesById).toLowerCase().includes(q)
            )
        }
        if (subFilters.sourceType !== "all") f = f.filter((s) => s.referral_source_type === subFilters.sourceType)
        if (subFilters.status !== "all") f = f.filter((s) => s.status === subFilters.status)
        if (subFilters.urgent !== "all") f = f.filter((s) => s.urgent_placement === (subFilters.urgent === "true"))
        if (subFilters.assigned === "me" && currentUserId) f = f.filter((s) => s.assigned_to_user_id === currentUserId)
        if (subFilters.assigned === "unassigned") f = f.filter((s) => !s.assigned_to_user_id)
        return [...f].sort((a, b) => {
            const colKey = submissionSort.column
            let aV: unknown
            let bV: unknown
            if (colKey === "program_display") {
                aV = submissionProgramDisplay(a, programNamesById)
                bV = submissionProgramDisplay(b, programNamesById)
            } else if (colKey === "assignee_display") {
                const pa = a.assigned_to_user_id ? staffAssigneeByUserId[a.assigned_to_user_id] : undefined
                const pb = b.assigned_to_user_id ? staffAssigneeByUserId[b.assigned_to_user_id] : undefined
                aV = pa?.display_name?.trim() || (a.assigned_to_user_id ? "Staff" : "")
                bV = pb?.display_name?.trim() || (b.assigned_to_user_id ? "Staff" : "")
            } else {
                aV = a[colKey as keyof ReferralSubmission]
                bV = b[colKey as keyof ReferralSubmission]
            }
            if (colKey === "created_at" || colKey === "archived_at" || colKey === "updated_at") {
                aV = new Date((aV as string) || 0).getTime()
                bV = new Date((bV as string) || 0).getTime()
            }
            const aS = String(aV ?? "")
            const bS = String(bV ?? "")
            return submissionSort.direction === "asc" ? aS.localeCompare(bS) : bS.localeCompare(aS)
        })
    }, [archivedSubmissions, searchQuery, subFilters, submissionSort, currentUserId, programNamesById, staffAssigneeByUserId])

    const filteredInquiries = useMemo(() => {
        let f = archivedInquiries
        if (searchQuery) {
            const q = searchQuery.toLowerCase()
            f = f.filter((i) =>
                (i.referral_source_name || "").toLowerCase().includes(q) ||
                (i.client_first_name || "").toLowerCase().includes(q) ||
                (i.client_last_initial || "").toLowerCase().includes(q) ||
                (i.client_current_location || "").toLowerCase().includes(q)
            )
        }
        if (inqFilters.inquiryType !== "all") f = f.filter((i) => i.inquiry_type === inqFilters.inquiryType)
        if (inqFilters.status !== "all") f = f.filter((i) => i.status === inqFilters.status)
        return [...f].sort((a, b) => {
            const col = inquirySort.column as keyof ReferralInquiry
            let aV: unknown = a[col]
            let bV: unknown = b[col]
            if (col === "created_at" || col === "archived_at" || col === "updated_at") {
                aV = new Date((aV as string) || 0).getTime()
                bV = new Date((bV as string) || 0).getTime()
            }
            const aS = String(aV ?? "")
            const bS = String(bV ?? "")
            return inquirySort.direction === "asc" ? aS.localeCompare(bS) : bS.localeCompare(aS)
        })
    }, [archivedInquiries, searchQuery, inqFilters, inquirySort])

    const currentData = innerTab === "submissions" ? filteredSubmissions : filteredInquiries
    const activeSelected = innerTab === "submissions" ? selectedSubs : selectedInqs
    const setActiveSelected = innerTab === "submissions" ? setSelectedSubs : setSelectedInqs
    const currentSort = innerTab === "submissions" ? submissionSort : inquirySort

    const handleSort = (column: string) => {
        const setter = innerTab === "submissions" ? setSubmissionSort : setInquirySort
        const current = innerTab === "submissions" ? submissionSort : inquirySort
        if (column === current.column) setter({ column, direction: current.direction === "asc" ? "desc" : "asc" })
        else setter({ column, direction: "asc" })
    }

    const toggleRowSelection = (id: string) => {
        const s = new Set(activeSelected)
        if (s.has(id)) s.delete(id)
        else s.add(id)
        setActiveSelected(s)
    }

    const toggleSelectAll = () => {
        if (activeSelected.size === currentData.length && currentData.length > 0) setActiveSelected(new Set())
        else setActiveSelected(new Set(currentData.map((r) => r.id)))
    }

    const recoverSelected = () => {
        const table = innerTab === "submissions" ? "referral_submissions" : "referral_inquiries"
        onRequestRecover(Array.from(activeSelected), table)
        setActiveSelected(new Set())
    }

    const archiveSubGrid =
        "40px minmax(96px,1.08fr) 52px minmax(68px,0.62fr) minmax(96px,0.72fr) minmax(88px,0.72fr) minmax(80px,0.6fr) minmax(88px,0.56fr) minmax(88px,0.5fr) minmax(120px,max-content)"
    const archiveInqGrid = "40px 1.4fr 0.8fr 1fr 1.2fr 0.9fr 0.9fr 1fr"
    const currentGrid = innerTab === "submissions" ? archiveSubGrid : archiveInqGrid
    const tableMinWidth = innerTab === "submissions" ? 1040 : 860
    const tCell = tableCellStyle(isCompactTable && innerTab === "submissions")
    const totalArchived = archivedSubmissions.length + archivedInquiries.length

    return (
        <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flexShrink: 0, marginBottom: 12 }}>
                <h2 style={{ margin: 0, fontSize: "22px", fontWeight: 700, color: COLORS.ash, fontFamily: FONT }}>Archive</h2>
                <p style={{ margin: "6px 0 0", fontSize: "13px", color: COLORS.ashMuted, lineHeight: 1.5, fontFamily: FONT }}>
                    Referrals and inquiries hidden from the active dashboard — recover any time to restore them.
                </p>
            </div>

            <div style={{ display: "flex", gap: 8, marginBottom: 16, flexShrink: 0, flexWrap: "wrap" }}>
                {(
                    [
                        { key: "submissions" as const, label: "Referral Submissions", count: archivedSubmissions.length },
                        { key: "inquiries" as const, label: "Inquiries", count: archivedInquiries.length },
                    ] as const
                ).map((tab) => (
                    <button
                        key={tab.key}
                        type="button"
                        onClick={() => {
                            setInnerTab(tab.key)
                            setSearchQuery("")
                            setSelectedSubs(new Set())
                            setSelectedInqs(new Set())
                        }}
                        style={{
                            ...pillBtnBase,
                            padding: "8px 16px",
                            fontSize: "13px",
                            background: innerTab === tab.key ? COLORS.ash : COLORS.white,
                            color: innerTab === tab.key ? COLORS.white : COLORS.ash,
                            border: `1px solid ${innerTab === tab.key ? COLORS.ash : COLORS.ashSubtle}`,
                        }}
                    >
                        {tab.label}
                        <span style={{ marginLeft: 8, fontSize: "11px", fontWeight: 700, opacity: 0.85 }}>{tab.count}</span>
                    </button>
                ))}
            </div>

            {activeSelected.size > 0 && (
                <div
                    style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 12,
                        marginBottom: 12,
                        padding: "10px 14px",
                        background: COLORS.moonstoneLight,
                        borderRadius: RADIUS.small,
                        flexShrink: 0,
                    }}
                >
                    <span style={{ fontSize: 13, color: COLORS.ash, fontWeight: 600, fontFamily: FONT }}>
                        {activeSelected.size} selected
                    </span>
                    <button type="button" onClick={recoverSelected} style={{ ...pillBtnBase, padding: "8px 14px", fontSize: "13px", background: COLORS.ash, color: COLORS.white }}>
                        Recover to dashboard
                    </button>
                    <button type="button" onClick={() => setActiveSelected(new Set())} style={{ ...pillBtnBase, padding: "8px 14px", fontSize: "13px", background: COLORS.white, color: COLORS.ashMuted, border: `1px solid ${COLORS.ashSubtle}` }}>
                        Clear selection
                    </button>
                </div>
            )}

            <div style={{ background: COLORS.white, borderRadius: RADIUS.container, boxShadow: SHADOWS.card, overflow: "hidden", flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
                <div style={{ padding: "16px 20px", display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center", borderBottom: `1px solid ${COLORS.ashSubtle}`, flexShrink: 0 }}>
                    <input
                        type="text"
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        style={{ ...selectStyle, width: isNarrow ? "100%" : "200px", backgroundImage: "none", paddingRight: "20px", boxSizing: "border-box" }}
                    />
                    {innerTab === "submissions" ? (
                        <>
                            <select value={subFilters.sourceType} onChange={(e) => setSubFilters({ ...subFilters, sourceType: e.target.value })} style={selectStyle} aria-label="Filter by source type">
                                <option value="all">All Types</option>
                                {Object.entries(SOURCE_TYPE_LABELS).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
                            </select>
                            <select value={subFilters.status} onChange={(e) => setSubFilters({ ...subFilters, status: e.target.value })} style={selectStyle} aria-label="Filter by status">
                                <option value="all">All Status</option>
                                {STATUS_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                            </select>
                        </>
                    ) : (
                        <>
                            <select value={inqFilters.inquiryType} onChange={(e) => setInqFilters({ ...inqFilters, inquiryType: e.target.value })} style={selectStyle} aria-label="Filter by inquiry type">
                                <option value="all">All Types</option>
                                <option value="self">Self</option>
                                <option value="other">Someone Else</option>
                            </select>
                            <select value={inqFilters.status} onChange={(e) => setInqFilters({ ...inqFilters, status: e.target.value })} style={selectStyle} aria-label="Filter by status">
                                <option value="all">All Status</option>
                                {STATUS_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                            </select>
                        </>
                    )}
                    <span style={{ fontSize: "12px", color: COLORS.ashMuted, marginLeft: "auto", fontFamily: FONT }}>
                        {currentData.length} result{currentData.length === 1 ? "" : "s"}
                        {totalArchived > 0 ? ` · ${totalArchived} archived total` : ""}
                    </span>
                </div>

                <div style={{ flex: 1, minHeight: 0, overflow: "auto", overscrollBehavior: "contain" }}>
                    <div style={{ minWidth: tableMinWidth }}>
                        <div style={{ display: "grid", gridTemplateColumns: currentGrid, background: COLORS.gunmetal }}>
                            <div style={{ ...(innerTab === "submissions" ? tCell : cellStyle), ...TABLE_COLUMN_HEADER_STYLE, display: "flex", justifyContent: "center" }}>
                                <input type="checkbox" checked={activeSelected.size === currentData.length && currentData.length > 0} onChange={toggleSelectAll} style={{ accentColor: COLORS.moonstone }} aria-label="Select all" />
                            </div>
                            {innerTab === "submissions" ? (
                                <>
                                    <HeaderCell compact={isCompactTable} column="client_first_name" label="Client" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact column="program_display" label="Prog" title="Program" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact={isCompactTable} column="assignee_display" label="Assignee" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact column="status" label="Stat" title="Status" sortable={false} sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact={isCompactTable} column="referral_source_name" label="Source" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact={isCompactTable} column="created_at" label="Submitted" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact={isCompactTable} column="archived_at" label="Archived" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell compact column="actions" label="Actions" sortable={false} sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                </>
                            ) : (
                                <>
                                    <HeaderCell column="referral_source_name" label="Contact" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell column="inquiry_type" label="Type" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell column="client_first_name" label="Client" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell column="client_current_location" label="Location" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell column="created_at" label="Date" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <HeaderCell column="archived_at" label="Archived" sortColumn={currentSort.column} sortDirection={currentSort.direction} onSort={handleSort} />
                                    <div style={{ ...cellStyle, ...TABLE_COLUMN_HEADER_STYLE }}>Actions</div>
                                </>
                            )}
                        </div>

                        {totalArchived === 0 ? (
                            <div style={{ padding: "48px 20px", textAlign: "center", color: COLORS.ashMuted, fontFamily: FONT, fontSize: "14px" }}>
                                No archived records — use Archive on a row in Referral Submissions or Inquiries to hide one from the active dashboard.
                            </div>
                        ) : currentData.length === 0 ? (
                            <div style={{ padding: "48px 20px", textAlign: "center", color: COLORS.ashMuted, fontFamily: FONT, fontSize: "14px" }}>
                                No results match your search or filters.
                            </div>
                        ) : innerTab === "submissions" ? (
                            filteredSubmissions.map((row, i) => {
                                const programCell = submissionProgramTableDisplay(row, programNamesById)
                                return (
                                    <div
                                        key={row.id}
                                        style={{
                                            display: "grid",
                                            gridTemplateColumns: archiveSubGrid,
                                            alignItems: "center",
                                            fontSize: "14px",
                                            fontFamily: FONT,
                                            color: COLORS.ash,
                                            borderBottom: i < filteredSubmissions.length - 1 ? `1px solid ${COLORS.ashSubtle}` : "none",
                                            background: selectedSubs.has(row.id) ? COLORS.champagneLight : i % 2 === 0 ? COLORS.white : COLORS.coconut,
                                        }}
                                    >
                                        <div style={{ ...tCell, display: "flex", justifyContent: "center" }}>
                                            <input type="checkbox" checked={selectedSubs.has(row.id)} onChange={() => toggleRowSelection(row.id)} style={{ accentColor: COLORS.moonstone }} />
                                        </div>
                                        <div style={{ ...tCell, ...kanbanClientNameStyle({ fontSize: isCompactTable ? 13 : 14, minWidth: 0 }) }} title={`${row.client_first_name || ""} ${row.client_last_name || ""}`.trim()}>
                                            {formatClientTableName(row.client_first_name, row.client_last_name, isCompactTable)}
                                        </div>
                                        <div style={{ ...tCell, fontSize: "13px", fontWeight: 600 }} title={programCell.full}>{programCell.abbrev}</div>
                                        <div style={{ ...tCell, fontSize: "12px", minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                                            {row.assigned_to_user_id
                                                ? staffAssigneeByUserId[row.assigned_to_user_id]?.display_name?.trim() || (row.assigned_to_user_id === currentUserId ? "You" : "Staff")
                                                : "\u2014"}
                                        </div>
                                        <div style={{ ...tCell, minWidth: 0 }} onClick={(e) => e.stopPropagation()}>
                                            <StatusDropdown currentStatus={row.status} onUpdate={(status) => onStatusUpdate(row.id, status, "referral_submissions")} disabled={updatingStatus === row.id} />
                                        </div>
                                        <div style={{ ...tCell, fontSize: "13px" }} title={row.referral_source_name || undefined}>{row.referral_source_name}</div>
                                        <div style={{ ...tCell, fontSize: "13px" }}>{formatTableDate(row.created_at, isCompactTable)}</div>
                                        <div style={{ ...tCell, fontSize: "13px" }}>{formatTableDate(row.archived_at, isCompactTable)}</div>
                                        <div style={{ ...tCell, display: "flex", gap: "4px", justifyContent: "flex-end" }}>
                                            <ActionButton compact={isCompactTable} onClick={() => onOpenSubmission(row)} title="View Details">View</ActionButton>
                                            <ActionButton compact={isCompactTable} onClick={() => onRequestRecover([row.id], "referral_submissions")} title="Recover to dashboard">{"\u21A9"}</ActionButton>
                                        </div>
                                    </div>
                                )
                            })
                        ) : (
                            filteredInquiries.map((row, i) => (
                                <div
                                    key={row.id}
                                    style={{
                                        display: "grid",
                                        gridTemplateColumns: archiveInqGrid,
                                        alignItems: "center",
                                        fontSize: "14px",
                                        fontFamily: FONT,
                                        color: COLORS.ash,
                                        borderBottom: i < filteredInquiries.length - 1 ? `1px solid ${COLORS.ashSubtle}` : "none",
                                        background: selectedInqs.has(row.id) ? COLORS.champagneLight : i % 2 === 0 ? COLORS.white : COLORS.coconut,
                                    }}
                                >
                                    <div style={{ ...cellStyle, display: "flex", justifyContent: "center" }}>
                                        <input type="checkbox" checked={selectedInqs.has(row.id)} onChange={() => toggleRowSelection(row.id)} style={{ accentColor: COLORS.moonstone }} />
                                    </div>
                                    <div style={{ ...cellStyle, fontWeight: 500 }}>{row.referral_source_name}</div>
                                    <div style={{ ...cellStyle, fontSize: "13px" }}>{formatLabel(row.inquiry_type)}</div>
                                    <div style={{ ...cellStyle, fontSize: "13px" }}>{row.client_first_name} {row.client_last_initial ? `${row.client_last_initial}.` : ""}</div>
                                    <div style={{ ...cellStyle, fontSize: "13px" }}>{formatLabel(row.client_current_location, LOCATION_LABELS)}</div>
                                    <div style={{ ...cellStyle, fontSize: "13px" }}>{formatDate(row.created_at)}</div>
                                    <div style={{ ...cellStyle, fontSize: "13px" }}>{formatDate(row.archived_at)}</div>
                                    <div style={{ ...cellStyle, display: "flex", gap: "4px" }}>
                                        <ActionButton onClick={() => onOpenInquiry(row)} title="View Details">View</ActionButton>
                                        <ActionButton onClick={() => onRequestRecover([row.id], "referral_inquiries")} title="Recover to dashboard">{"\u21A9"}</ActionButton>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
        </div>
    )
}

// ============================================================================
// MESSAGES (referral threads inbox)
// ============================================================================

type DashboardMessageRow = {
    id: string
    referral_id: string
    from_user_id?: string | null
    from_email: string | null
    body: string
    created_at: string
}

type DashboardMessageInboxFilter = "all" | "unread"

type DashboardMessageThreadSummary = {
    referralId: string
    submission: ReferralSubmission
    lastMessage: DashboardMessageRow | null
    messageCount: number
    unread: boolean
}

function formatDashboardMessageTime(iso: string): string {
    const d = new Date(iso)
    if (Number.isNaN(d.getTime())) return ""
    const now = new Date()
    const diffMins = Math.floor((now.getTime() - d.getTime()) / 60000)
    if (diffMins < 1) return "Just now"
    if (diffMins < 60) return `${diffMins}m ago`
    const diffHours = Math.floor(diffMins / 60)
    if (diffHours < 24) return `${diffHours}h ago`
    const diffDays = Math.floor(diffHours / 24)
    if (diffDays === 1) return "Yesterday"
    if (diffDays < 7) return `${diffDays}d ago`
    return d.toLocaleDateString(undefined, { month: "short", day: "numeric" })
}

function formatDashboardMessageDayLabel(iso: string): string {
    const d = new Date(iso)
    if (Number.isNaN(d.getTime())) return ""
    const now = new Date()
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
    const msgDay = new Date(d.getFullYear(), d.getMonth(), d.getDate())
    const diffDays = Math.round((today.getTime() - msgDay.getTime()) / 86400000)
    if (diffDays === 0) return "Today"
    if (diffDays === 1) return "Yesterday"
    return d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })
}

function isStaffReferralMessage(msg: DashboardMessageRow, userId: string | null, _userEmail: string | null): boolean {
    if (userId && msg.from_user_id && msg.from_user_id === userId) return true
    return isStaffEmailForProgram(msg.from_email)
}

function buildDashboardMessageThreadSummaries(
    submissions: ReferralSubmission[],
    messagesByReferral: Record<string, DashboardMessageRow[]>,
    openThreadIds?: Set<string>
): DashboardMessageThreadSummary[] {
    const summaries: DashboardMessageThreadSummary[] = []
    for (const submission of submissions) {
        const messages = messagesByReferral[submission.id] ?? []
        const hasMessages = messages.length > 0
        const forceInclude = openThreadIds?.has(submission.id)
        if (!hasMessages && !forceInclude) continue
        summaries.push({
            referralId: submission.id,
            submission,
            lastMessage: hasMessages ? messages[messages.length - 1]! : null,
            messageCount: messages.length,
            unread: !!submission.has_unread_messages,
        })
    }
    return summaries.sort((a, b) => {
        if (a.unread !== b.unread) return a.unread ? -1 : 1
        const aTime = a.lastMessage ? new Date(a.lastMessage.created_at).getTime() : 0
        const bTime = b.lastMessage ? new Date(b.lastMessage.created_at).getTime() : 0
        return bTime - aTime
    })
}

function filterDashboardMessageThreads(items: DashboardMessageThreadSummary[], filter: DashboardMessageInboxFilter) {
    if (filter === "unread") return items.filter((item) => item.unread)
    return items
}

function dashboardMessageThreadTitle(s: ReferralSubmission): string {
    return `${s.client_first_name || ""} ${s.client_last_name || ""}`.trim() || "Referral"
}

function dashboardMessageThreadSubtitle(s: ReferralSubmission, programNamesById: Record<string, string>): string {
    const program = submissionProgramTableDisplay(s, programNamesById).abbrev
    return `${referralDisplayId(s)} · ${s.referral_source_name || "—"} · ${program}`
}

const DASHBOARD_MESSAGES_THREAD_LIST_WIDTH = 280
const DASHBOARD_MESSAGES_SEARCH_RAIL_WIDTH = 260

function DashboardMessagesReferralSearchRail({
    submissions,
    selectedReferralId,
    onSelectReferral,
    programNamesById,
    currentUserId,
    staffAssigneeByUserId,
}: {
    submissions: ReferralSubmission[]
    selectedReferralId: string | null
    onSelectReferral: (referralId: string) => void
    programNamesById: Record<string, string>
    currentUserId: string | null
    staffAssigneeByUserId: Record<string, AdmissionsStaffProfile | undefined>
}) {
    const [search, setSearch] = useState("")
    const [mineOnly, setMineOnly] = useState(false)

    const results = useMemo(() => {
        const activeStatuses: ReferralStatus[] = ["pending_review", "under_review", "waitlisted", "accepted"]
        let list = submissions.filter((s) => activeStatuses.includes(s.status))
        if (mineOnly && currentUserId) {
            list = list.filter((s) => s.assigned_to_user_id === currentUserId)
        }
        const q = search.trim().toLowerCase()
        if (!q) return list.slice(0, 12)
        return list
            .filter((s) => {
                const haystack = [
                    s.client_first_name,
                    s.client_last_name,
                    s.admin_ref_id,
                    s.referral_code,
                    s.referral_source_name,
                    s.referral_source_organization,
                    submissionProgramTableDisplay(s, programNamesById).abbrev,
                ]
                    .join(" ")
                    .toLowerCase()
                return haystack.includes(q)
            })
            .slice(0, 20)
    }, [submissions, search, mineOnly, currentUserId, programNamesById])

    return (
        <div
            style={{
                width: DASHBOARD_MESSAGES_SEARCH_RAIL_WIDTH,
                flexShrink: 0,
                display: "flex",
                flexDirection: "column",
                minHeight: 0,
                borderLeft: `1px solid ${COLORS.ashSubtle}`,
                background: COLORS.white,
                fontFamily: FONT,
            }}
        >
            <div style={{ flexShrink: 0, padding: "16px 16px 12px", borderBottom: `1px solid ${COLORS.ashSubtle}` }}>
                <h3 style={{ margin: 0, fontSize: 14, fontWeight: 700, color: COLORS.ash }}>Find referral</h3>
                <p style={{ margin: "6px 0 12px", fontSize: 11, color: COLORS.ashMuted, lineHeight: 1.4 }}>
                    Search active referrals to open or start that case&apos;s thread.
                </p>
                <input
                    type="search"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Client, REF ID, source…"
                    aria-label="Search referrals to message"
                    style={{
                        width: "100%",
                        padding: "9px 12px",
                        fontSize: 13,
                        fontFamily: FONT,
                        border: `1px solid ${COLORS.ashSubtle}`,
                        borderRadius: RADIUS.small,
                        background: COLORS.coconut25,
                        color: COLORS.ash,
                        boxSizing: "border-box",
                        marginBottom: 10,
                    }}
                />
                <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, fontWeight: 600, color: COLORS.ashMuted, cursor: "pointer" }}>
                    <input type="checkbox" checked={mineOnly} onChange={(e) => setMineOnly(e.target.checked)} style={{ accentColor: COLORS.moonstone }} />
                    My assignments only
                </label>
            </div>
            <div style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
                {results.length === 0 ? (
                    <p style={{ padding: 16, margin: 0, fontSize: 12, color: COLORS.ashMuted }}>No matching referrals.</p>
                ) : (
                    results.map((s) => {
                        const selected = selectedReferralId === s.id
                        const assignee = s.assigned_to_user_id ? staffAssigneeByUserId[s.assigned_to_user_id] : undefined
                        const assigneeLabel = assignee?.display_name?.trim() || (s.assigned_to_user_id === currentUserId ? "You" : "Unassigned")
                        return (
                            <button
                                key={s.id}
                                type="button"
                                onClick={() => onSelectReferral(s.id)}
                                style={{
                                    width: "100%",
                                    textAlign: "left",
                                    padding: "12px 16px",
                                    border: "none",
                                    borderBottom: `1px solid ${COLORS.ashSubtle}`,
                                    background: selected ? COLORS.moonstoneLight : COLORS.white,
                                    cursor: "pointer",
                                    fontFamily: FONT,
                                }}
                            >
                                <div style={{ fontSize: 13, fontWeight: 600, color: COLORS.ash, marginBottom: 4 }}>
                                    {dashboardMessageThreadTitle(s)}
                                </div>
                                <div style={{ fontSize: 11, color: COLORS.ashMuted, lineHeight: 1.4 }}>
                                    {referralDisplayId(s)} · {formatLabel(s.status)}
                                </div>
                                <div style={{ fontSize: 11, color: COLORS.ashMuted, marginTop: 4 }}>{assigneeLabel}</div>
                            </button>
                        )
                    })
                )}
            </div>
        </div>
    )
}

const DashboardMessagesWorkspace = ({
    submissions,
    messagesByReferral,
    messagesLoading,
    selectedReferralId,
    onSelectionChange,
    inboxFilter,
    onInboxFilterChange,
    openThreadIds,
    programNamesById,
    staffDisplayName,
    userId,
    userEmail,
    onSendMessage,
    sendingMessage,
    onOpenReferral,
    staffAssigneeByUserId,
}: {
    submissions: ReferralSubmission[]
    messagesByReferral: Record<string, DashboardMessageRow[]>
    messagesLoading?: boolean
    selectedReferralId: string | null
    onSelectionChange: (referralId: string | null) => void
    inboxFilter: DashboardMessageInboxFilter
    onInboxFilterChange: (filter: DashboardMessageInboxFilter) => void
    openThreadIds: Set<string>
    programNamesById: Record<string, string>
    staffDisplayName: string
    userId: string | null
    userEmail: string | null
    onSendMessage: (referralId: string, body: string) => void
    sendingMessage?: boolean
    onOpenReferral?: (submission: ReferralSubmission) => void
    staffAssigneeByUserId: Record<string, AdmissionsStaffProfile | undefined>
}) => {
    const [draft, setDraft] = useState("")
    const scrollRef = useRef<HTMLDivElement>(null)
    const threadSummaries = useMemo(
        () => buildDashboardMessageThreadSummaries(submissions, messagesByReferral, openThreadIds),
        [submissions, messagesByReferral, openThreadIds]
    )
    const filteredThreads = filterDashboardMessageThreads(threadSummaries, inboxFilter)
    const selectedSubmission = selectedReferralId ? submissions.find((s) => s.id === selectedReferralId) ?? null : null
    const selectedMessages = selectedReferralId ? messagesByReferral[selectedReferralId] ?? [] : []

    useEffect(() => {
        if (selectedReferralId || threadSummaries.length === 0) return
        onSelectionChange(threadSummaries[0]!.referralId)
    }, [selectedReferralId, threadSummaries, onSelectionChange])

    const grouped = useMemo(() => {
        const groups: { day: string; items: DashboardMessageRow[] }[] = []
        for (const msg of selectedMessages) {
            const day = formatDashboardMessageDayLabel(msg.created_at)
            const last = groups[groups.length - 1]
            if (last && last.day === day) last.items.push(msg)
            else groups.push({ day, items: [msg] })
        }
        return groups
    }, [selectedMessages])

    useEffect(() => {
        const el = scrollRef.current
        if (el) el.scrollTop = el.scrollHeight
    }, [selectedMessages, selectedReferralId])

    const handleSend = () => {
        const body = draft.trim()
        if (!body || !selectedReferralId || sendingMessage) return
        onSendMessage(selectedReferralId, body)
        setDraft("")
    }

    return (
        <div style={{ display: "flex", flex: 1, minHeight: 0, minWidth: 0, width: "100%", overflow: "hidden", fontFamily: FONT }}>
            <div
                style={{
                    width: DASHBOARD_MESSAGES_THREAD_LIST_WIDTH,
                    flexShrink: 0,
                    display: "flex",
                    flexDirection: "column",
                    minHeight: 0,
                    borderRight: `1px solid ${COLORS.ashSubtle}`,
                    background: COLORS.white,
                }}
            >
                <div style={{ flexShrink: 0, padding: "16px 18px", borderBottom: `1px solid ${COLORS.ashSubtle}` }}>
                    <h2 style={{ margin: 0, fontSize: 16, fontWeight: 600, color: COLORS.ash, fontFamily: FONT }}>Messages</h2>
                    <p style={{ margin: "6px 0 10px", fontSize: 12, color: COLORS.ashMuted, lineHeight: 1.45 }}>
                        Referral threads (one per case) with referral sources.
                    </p>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                        {(["all", "unread"] as const).map((id) => (
                            <button
                                key={id}
                                type="button"
                                onClick={() => onInboxFilterChange(id)}
                                style={{
                                    padding: "4px 10px",
                                    fontSize: 11,
                                    fontWeight: 600,
                                    fontFamily: FONT,
                                    border: `1px solid ${inboxFilter === id ? COLORS.moonstone : COLORS.ashSubtle}`,
                                    borderRadius: RADIUS.pill,
                                    background: inboxFilter === id ? COLORS.moonstoneLight : COLORS.white,
                                    color: inboxFilter === id ? COLORS.ash : COLORS.ashMuted,
                                    cursor: "pointer",
                                }}
                            >
                                {id === "all" ? "All" : "Unread"}
                            </button>
                        ))}
                    </div>
                </div>
                <div style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
                    {messagesLoading ? (
                        <p style={{ padding: 20, fontSize: 13, color: COLORS.ashMuted, margin: 0 }}>Loading threads…</p>
                    ) : filteredThreads.length === 0 ? (
                        <p style={{ padding: 20, fontSize: 13, color: COLORS.ashMuted, margin: 0 }}>
                            {inboxFilter === "unread" ? "No unread threads." : "No message threads yet."}
                        </p>
                    ) : (
                        filteredThreads.map((item) => {
                            const selected = selectedReferralId === item.referralId
                            return (
                                <button
                                    key={item.referralId}
                                    type="button"
                                    onClick={() => onSelectionChange(item.referralId)}
                                    style={{
                                        width: "100%",
                                        textAlign: "left",
                                        padding: "14px 18px",
                                        border: "none",
                                        borderBottom: `1px solid ${COLORS.ashSubtle}`,
                                        background: selected ? COLORS.moonstoneLight : item.unread ? COLORS.champagneLight : COLORS.white,
                                        cursor: "pointer",
                                        fontFamily: FONT,
                                    }}
                                >
                                    <div style={{ display: "flex", justifyContent: "space-between", gap: 8, marginBottom: 4 }}>
                                        <span style={{ fontSize: 14, fontWeight: 600, color: COLORS.ash, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", flex: 1 }}>
                                            {dashboardMessageThreadTitle(item.submission)}
                                        </span>
                                        {item.lastMessage ? (
                                            <span style={{ fontSize: 11, color: COLORS.ashMuted, flexShrink: 0 }}>
                                                {formatDashboardMessageTime(item.lastMessage.created_at)}
                                            </span>
                                        ) : null}
                                    </div>
                                    <div style={{ fontSize: 11, color: COLORS.ashMuted, marginBottom: 4 }}>
                                        {dashboardMessageThreadSubtitle(item.submission, programNamesById)}
                                    </div>
                                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                        {item.unread ? <span style={{ width: 8, height: 8, borderRadius: "50%", background: COLORS.moonstone, flexShrink: 0 }} aria-label="Unread" /> : null}
                                        <span style={{ fontSize: 13, color: COLORS.ashMuted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontWeight: item.unread ? 600 : 400 }}>
                                            {item.lastMessage?.body || "No messages yet"}
                                        </span>
                                    </div>
                                </button>
                            )
                        })
                    )}
                </div>
            </div>
            <div style={{ flex: 1, minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column", background: COLORS.coconut25 }}>
                {!selectedSubmission ? (
                    <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", color: COLORS.ashMuted, fontSize: 14 }}>
                        Select a referral thread to start messaging
                    </div>
                ) : (
                    <>
                        <div style={{ flexShrink: 0, padding: "14px 20px", borderBottom: `1px solid ${COLORS.ashSubtle}`, background: COLORS.white }}>
                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
                                <div style={{ minWidth: 0 }}>
                                    <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700, color: COLORS.ash }}>{dashboardMessageThreadTitle(selectedSubmission)}</h3>
                                    <p style={{ margin: "4px 0 0", fontSize: 12, color: COLORS.ashMuted }}>
                                        {dashboardMessageThreadSubtitle(selectedSubmission, programNamesById)} · {formatLabel(selectedSubmission.status)}
                                    </p>
                                </div>
                                {onOpenReferral ? (
                                    <button
                                        type="button"
                                        onClick={() => onOpenReferral(selectedSubmission)}
                                        style={{
                                            flexShrink: 0,
                                            padding: "8px 12px",
                                            fontSize: 12,
                                            fontWeight: 600,
                                            fontFamily: FONT,
                                            border: `1px solid ${COLORS.ashSubtle}`,
                                            borderRadius: RADIUS.small,
                                            background: COLORS.white,
                                            color: COLORS.ash,
                                            cursor: "pointer",
                                        }}
                                    >
                                        View record
                                    </button>
                                ) : null}
                            </div>
                        </div>
                        <div ref={scrollRef} style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "16px 20px", display: "flex", flexDirection: "column", gap: 16 }}>
                            {messagesLoading ? (
                                <p style={{ margin: "auto", fontSize: 13, color: COLORS.ashMuted }}>Loading messages…</p>
                            ) : selectedMessages.length === 0 ? (
                                <p style={{ margin: "auto", fontSize: 13, color: COLORS.ashMuted, textAlign: "center" }}>No messages yet. Send the first message about this referral.</p>
                            ) : (
                                grouped.map((group) => (
                                    <div key={group.day}>
                                        <div style={{ textAlign: "center", fontSize: 11, fontWeight: 600, color: COLORS.ashMuted, marginBottom: 12 }}>{group.day}</div>
                                        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                                            {group.items.map((msg) => {
                                                const isMine = isStaffReferralMessage(msg, userId, userEmail)
                                                const authorLabel = isMine ? staffDisplayName || "You" : msg.from_email || selectedSubmission.referral_source_name || "Referral source"
                                                return (
                                                    <div key={msg.id} style={{ display: "flex", flexDirection: "column", alignItems: isMine ? "flex-end" : "flex-start", maxWidth: "78%", alignSelf: isMine ? "flex-end" : "flex-start" }}>
                                                        <div style={{ fontSize: 10, fontWeight: 600, color: COLORS.ashMuted, marginBottom: 4 }}>
                                                            {authorLabel} · {formatDashboardMessageTime(msg.created_at)}
                                                        </div>
                                                        <div
                                                            style={{
                                                                padding: "10px 14px",
                                                                borderRadius: isMine ? "20px" : `${RADIUS.section} ${RADIUS.section} ${RADIUS.section} ${RADIUS.small}`,
                                                                background: isMine ? COLORS.messageSentBg : COLORS.white,
                                                                color: isMine ? "var(--foreground, #2B2828)" : COLORS.ash,
                                                                fontSize: 14,
                                                                lineHeight: 1.45,
                                                                border: isMine ? "none" : `1px solid ${COLORS.ashSubtle}`,
                                                                whiteSpace: "pre-wrap",
                                                                wordBreak: "break-word",
                                                            }}
                                                        >
                                                            {msg.body}
                                                        </div>
                                                    </div>
                                                )
                                            })}
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                        <div style={{ flexShrink: 0, padding: "12px 16px 16px", borderTop: `1px solid ${COLORS.ashSubtle}`, background: COLORS.white }}>
                            <div style={{ display: "flex", gap: 10, alignItems: "flex-end" }}>
                                <textarea
                                    value={draft}
                                    onChange={(e) => setDraft(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter" && !e.shiftKey) {
                                            e.preventDefault()
                                            handleSend()
                                        }
                                    }}
                                    placeholder={`Message ${selectedSubmission.referral_source_name || "referral source"} about this referral…`}
                                    rows={2}
                                    style={{ flex: 1, resize: "none", padding: "10px 12px", fontSize: 14, fontFamily: FONT, border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.section, background: COLORS.coconut25, color: "var(--foreground)", lineHeight: 1.4, boxSizing: "border-box" }}
                                />
                                <button
                                    type="button"
                                    onClick={handleSend}
                                    disabled={!draft.trim() || sendingMessage}
                                    style={{
                                        padding: "10px 18px",
                                        fontSize: 13,
                                        fontWeight: 600,
                                        fontFamily: FONT,
                                        border: "none",
                                        borderRadius: RADIUS.small,
                                        background: draft.trim() && !sendingMessage ? COLORS.ash : COLORS.ashSubtle,
                                        color: COLORS.white,
                                        cursor: draft.trim() && !sendingMessage ? "pointer" : "not-allowed",
                                    }}
                                >
                                    {sendingMessage ? "Sending…" : "Send"}
                                </button>
                            </div>
                            <p style={{ margin: "8px 0 0", fontSize: 11, color: COLORS.ashMuted }}>
                                Sending as {staffDisplayName} · Enter to send, Shift+Enter for new line
                            </p>
                        </div>
                    </>
                )}
            </div>
            <DashboardMessagesReferralSearchRail
                submissions={submissions}
                selectedReferralId={selectedReferralId}
                onSelectReferral={(id) => onSelectionChange(id)}
                programNamesById={programNamesById}
                currentUserId={userId}
                staffAssigneeByUserId={staffAssigneeByUserId}
            />
        </div>
    )
}

// ============================================================================
// DASHBOARD HEADER (Cases | Organizations | Contacts + date/clock)
// ============================================================================

type StaffDashboardTab = "cases" | "organizations" | "contacts"

const DashboardDateClock = () => {
    const [now, setNow] = useState(() => new Date())
    useEffect(() => {
        const id = window.setInterval(() => setNow(new Date()), 1000)
        return () => window.clearInterval(id)
    }, [])
    const tabText: React.CSSProperties = {
        fontSize: 12,
        fontWeight: 700,
        fontFamily: FONT_HEADING,
        letterSpacing: "0.08em",
        textTransform: "uppercase",
        color: COLORS.ash,
    }
    const month = now.toLocaleString("en-US", { month: "long" })
    const day = String(now.getDate()).padStart(2, "0")
    const year = now.getFullYear()
    const clock = now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", hour12: true })
    return (
        <div aria-live="polite" style={{ textAlign: "right", flexShrink: 0, paddingTop: 10, paddingBottom: 10, minWidth: 0 }}>
            <div style={tabText}>{`${month} ${day}/${year}`}</div>
            <div
                style={{
                    ...tabText,
                    fontSize: 48,
                    fontWeight: 700,
                    letterSpacing: "-0.02em",
                    textTransform: "none",
                    lineHeight: 1,
                    marginTop: 4,
                    fontVariantNumeric: "tabular-nums",
                }}
            >
                {clock}
            </div>
        </div>
    )
}

const StaffDashboardTabBar = ({
    active,
    onChange,
    embedded = false,
}: {
    active: StaffDashboardTab
    onChange: (tab: StaffDashboardTab) => void
    embedded?: boolean
}) => {
    const tabs: { id: StaffDashboardTab; label: string }[] = [
        { id: "cases", label: "Cases" },
        { id: "organizations", label: "Organizations" },
        { id: "contacts", label: "Contacts" },
    ]
    return (
        <div
            style={{
                display: "flex",
                gap: 4,
                marginBottom: embedded ? 0 : 16,
                flexShrink: 0,
                borderBottom: embedded ? "none" : `1px solid ${COLORS.ashSubtle}`,
                paddingBottom: 0,
                minWidth: 0,
            }}
        >
            {tabs.map((tab) => {
                const isActive = active === tab.id
                return (
                    <button
                        key={tab.id}
                        type="button"
                        onClick={() => onChange(tab.id)}
                        style={{
                            padding: "10px 20px",
                            fontSize: 12,
                            fontWeight: 600,
                            fontFamily: FONT_HEADING,
                            letterSpacing: "0.08em",
                            textTransform: "uppercase",
                            border: "none",
                            borderBottom: isActive ? `2px solid ${COLORS.primary}` : "2px solid transparent",
                            background: "transparent",
                            color: COLORS.ash,
                            opacity: isActive ? 1 : 0.75,
                            cursor: "pointer",
                            marginBottom: -1,
                        }}
                    >
                        {tab.label}
                    </button>
                )
            })}
        </div>
    )
}

const DashboardStaffHeader = ({
    active,
    onChange,
}: {
    active: StaffDashboardTab
    onChange: (tab: StaffDashboardTab) => void
}) => (
    <div
        style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 1fr) auto",
            alignItems: "start",
            columnGap: 24,
            marginBottom: 16,
            flexShrink: 0,
            borderBottom: `1px solid ${COLORS.ashSubtle}`,
            minWidth: 0,
        }}
    >
        <StaffDashboardTabBar active={active} onChange={onChange} embedded />
        <DashboardDateClock />
    </div>
)

// ============================================================================
// ORGANIZATIONS & CONTACTS (staff dashboard — Phase D; derived from submissions + local edits)
// ============================================================================

type OrganizationType =
    | "treatment_center"
    | "detention_center"
    | "community_center"
    | "health_wellness"
    | "county_jail"
    | "court"
    | "probation_parole"
    | "legal_representative"

const ORGANIZATION_TYPE_LABELS: Record<OrganizationType, string> = {
    treatment_center: "Treatment Center",
    detention_center: "Detention Center",
    community_center: "Community Center",
    health_wellness: "Health & Wellness",
    county_jail: "County Jail",
    court: "Court",
    probation_parole: "Probation / Parole",
    legal_representative: "Legal Representative",
}

interface DashboardOrganization {
    id: string
    name: string
    contact_name: string
    phone: string
    email: string
    organization_type: OrganizationType
    created_at: string
    source?: "referral" | "user"
}

type DashboardContactSource = "referral" | "user"

interface DashboardContact {
    id: string
    name: string
    organization: string
    organization_type: OrganizationType
    phone: string
    email: string
    url: string
    notes: string
    source: DashboardContactSource
    owner_user_id?: string
    referral_count: number
    last_active_at: string | null
    created_at: string
}

type ContactReferralCountFilter = "all" | "1plus" | "2plus" | "5plus"
type ContactLastActiveFilter = "all" | "30d" | "90d" | "1y"
type ContactSourceFilter = "all" | "referral" | "personal"

type ContactFilters = {
    search: string
    organization: string | "all"
    organizationType: OrganizationType | "all"
    referralCount: ContactReferralCountFilter
    lastActive: ContactLastActiveFilter
    source: ContactSourceFilter
}

const DEFAULT_CONTACT_FILTERS: ContactFilters = {
    search: "",
    organization: "all",
    organizationType: "all",
    referralCount: "all",
    lastActive: "all",
    source: "all",
}

const DIRECTORY_ORGS_STORAGE_KEY = "monarch-dashboard-user-organizations"
const DIRECTORY_CONTACTS_STORAGE_KEY = "monarch-dashboard-user-contacts"

function directoryOrgContactKey(name: string, contactOrOrg: string): string {
    return `${name.trim().toLowerCase()}|${contactOrOrg.trim().toLowerCase()}`
}

function directoryContactSlugId(name: string, organization: string): string {
    return directoryOrgContactKey(name, organization).replace(/[^a-z0-9]+/g, "-")
}

function referralSourceTypeToOrgType(sourceType: string | null | undefined): OrganizationType {
    switch (sourceType) {
        case "court":
            return "court"
        case "legal_representative":
            return "legal_representative"
        case "probation_parole":
            return "probation_parole"
        case "mental_health_facility":
            return "treatment_center"
        default:
            return "community_center"
    }
}

function matchesDirectoryOrganization(referral: ReferralSubmission, org: DashboardOrganization): boolean {
    const orgMatch =
        (referral.referral_source_organization || "").trim().toLowerCase() === org.name.trim().toLowerCase()
    const contactMatch = (referral.referral_source_name || "").trim().toLowerCase() === org.contact_name.trim().toLowerCase()
    return orgMatch && contactMatch
}

function referralsForDirectoryOrganization(referrals: ReferralSubmission[], org: DashboardOrganization): ReferralSubmission[] {
    return referrals.filter((r) => matchesDirectoryOrganization(r, org))
}

function matchesDirectoryContact(referral: ReferralSubmission, contact: DashboardContact): boolean {
    return (
        directoryOrgContactKey(referral.referral_source_name, referral.referral_source_organization || "") ===
        directoryOrgContactKey(contact.name, contact.organization)
    )
}

function referralsForDirectoryContact(referrals: ReferralSubmission[], contact: DashboardContact): ReferralSubmission[] {
    return referrals.filter((r) => matchesDirectoryContact(r, contact))
}

function buildOrganizationsFromSubmissions(submissions: ReferralSubmission[]): DashboardOrganization[] {
    const map = new Map<string, DashboardOrganization>()
    for (const s of submissions) {
        const name = (s.referral_source_organization || "").trim()
        const contact = (s.referral_source_name || "").trim()
        if (!name && !contact) continue
        const key = directoryOrgContactKey(name || "—", contact || "—")
        const existing = map.get(key)
        if (existing) {
            if (!existing.phone && s.referral_source_phone) existing.phone = s.referral_source_phone
            if (!existing.email && s.referral_source_email) existing.email = s.referral_source_email
            continue
        }
        map.set(key, {
            id: `org-ref-${directoryContactSlugId(name || "org", contact || "contact")}`,
            name: name || "—",
            contact_name: contact || "—",
            phone: s.referral_source_phone || "",
            email: s.referral_source_email || "",
            organization_type: referralSourceTypeToOrgType(s.referral_source_type),
            created_at: s.created_at,
            source: "referral",
        })
    }
    return [...map.values()].sort((a, b) => a.name.localeCompare(b.name))
}

function buildContactsFromSubmissions(submissions: ReferralSubmission[]): DashboardContact[] {
    const map = new Map<string, { referrals: ReferralSubmission[]; orgType: OrganizationType }>()
    for (const referral of submissions) {
        const name = (referral.referral_source_name || "").trim()
        const org = (referral.referral_source_organization || "").trim()
        if (!name) continue
        const key = directoryOrgContactKey(name, org)
        const existing = map.get(key)
        if (existing) existing.referrals.push(referral)
        else map.set(key, { referrals: [referral], orgType: referralSourceTypeToOrgType(referral.referral_source_type) })
    }
    const contacts: DashboardContact[] = []
    for (const { referrals: matching, orgType } of map.values()) {
        const sample = matching[0]!
        const lastActive = matching.reduce<string | null>((latest, r) => {
            const candidate = r.last_activity_at ?? r.created_at
            if (!latest) return candidate
            return new Date(candidate) > new Date(latest) ? candidate : latest
        }, null)
        contacts.push({
            id: `contact-ref-${directoryContactSlugId(sample.referral_source_name, sample.referral_source_organization || "")}`,
            name: sample.referral_source_name,
            organization: sample.referral_source_organization || "",
            organization_type: orgType,
            phone: sample.referral_source_phone || "",
            email: sample.referral_source_email || "",
            url: "",
            notes: "",
            source: "referral",
            referral_count: matching.length,
            last_active_at: lastActive,
            created_at: matching.reduce((earliest, r) => (!earliest || new Date(r.created_at) < new Date(earliest) ? r.created_at : earliest), matching[0].created_at),
        })
    }
    return contacts.sort((a, b) => a.name.localeCompare(b.name))
}

function mergeDirectoryOrganizations(derived: DashboardOrganization[], userAdded: DashboardOrganization[]): DashboardOrganization[] {
    const byId = new Map<string, DashboardOrganization>()
    for (const o of derived) byId.set(o.id, o)
    for (const o of userAdded) byId.set(o.id, o)
    return [...byId.values()].sort((a, b) => a.name.localeCompare(b.name))
}

function mergeDirectoryContacts(derived: DashboardContact[], userAdded: DashboardContact[]): DashboardContact[] {
    const byId = new Map<string, DashboardContact>()
    for (const c of derived) byId.set(c.id, c)
    for (const c of userAdded) byId.set(c.id, c)
    return [...byId.values()]
}

type OrganizationReferralStats = {
    total: number
    active: number
    pending_review: number
    under_review: number
    accepted: number
    declined: number
    waitlisted: number
    this_week: number
}

const DIRECTORY_ACTIVE_STATUSES: ReferralStatus[] = ["pending_review", "under_review"]

function organizationReferralStats(referrals: ReferralSubmission[], org: DashboardOrganization): OrganizationReferralStats {
    const matching = referralsForDirectoryOrganization(referrals, org)
    const weekAgo = new Date()
    weekAgo.setDate(weekAgo.getDate() - 7)
    const thisWeek = matching.filter((r) => {
        const d = new Date(r.created_at)
        return !Number.isNaN(d.getTime()) && d >= weekAgo
    }).length
    return {
        total: matching.length,
        active: matching.filter((r) => DIRECTORY_ACTIVE_STATUSES.includes(r.status)).length,
        pending_review: matching.filter((r) => r.status === "pending_review").length,
        under_review: matching.filter((r) => r.status === "under_review").length,
        accepted: matching.filter((r) => r.status === "accepted").length,
        declined: matching.filter((r) => r.status === "declined").length,
        waitlisted: matching.filter((r) => r.status === "waitlisted").length,
        this_week: thisWeek,
    }
}

type OrganizationListStats = { total: number; newThisMonth: number; multiReferral: number; admitted: number; thisWeek: number }

function organizationListStats(organizations: DashboardOrganization[], referrals: ReferralSubmission[]): OrganizationListStats {
    const now = new Date()
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1)
    const weekAgo = new Date(now)
    weekAgo.setDate(weekAgo.getDate() - 7)
    const referralCounts = organizations.map((org) => referralsForDirectoryOrganization(referrals, org).length)
    return {
        total: organizations.length,
        newThisMonth: organizations.filter((org) => {
            const d = new Date(org.created_at)
            return !Number.isNaN(d.getTime()) && d >= monthStart
        }).length,
        multiReferral: referralCounts.filter((c) => c > 1).length,
        admitted: referrals.filter((r) => r.status === "accepted").length,
        thisWeek: referrals.filter((r) => {
            const d = new Date(r.created_at)
            return !Number.isNaN(d.getTime()) && d >= weekAgo
        }).length,
    }
}

function filterOrganizationsList(
    organizations: DashboardOrganization[],
    search: string,
    typeFilter: OrganizationType | "all"
): DashboardOrganization[] {
    let result = [...organizations]
    const q = search.trim().toLowerCase()
    if (q) {
        result = result.filter((org) =>
            [org.name, org.contact_name, org.phone, org.email, org.organization_type].join(" ").toLowerCase().includes(q)
        )
    }
    if (typeFilter !== "all") result = result.filter((org) => org.organization_type === typeFilter)
    return result.sort((a, b) => a.name.localeCompare(b.name))
}

type ContactListStats = { total: number; hasReferred: number; personal: number; activeThisWeek: number; multiReferral: number }

function contactsVisibleToUser(contacts: DashboardContact[], userId: string | null): DashboardContact[] {
    if (!userId) return contacts.filter((c) => c.source === "referral")
    return contacts.filter((c) => c.source === "referral" || c.owner_user_id === userId)
}

function contactOrganizationOptions(contacts: DashboardContact[]): string[] {
    return [...new Set(contacts.map((c) => c.organization).filter(Boolean))].sort((a, b) => a.localeCompare(b))
}

function passesContactReferralCountFilter(count: number, filter: ContactReferralCountFilter): boolean {
    if (filter === "1plus") return count >= 1
    if (filter === "2plus") return count >= 2
    if (filter === "5plus") return count >= 5
    return true
}

function passesContactLastActiveFilter(lastActive: string | null, filter: ContactLastActiveFilter): boolean {
    if (filter === "all") return true
    if (!lastActive) return false
    const d = new Date(lastActive)
    if (Number.isNaN(d.getTime())) return false
    const days = filter === "30d" ? 30 : filter === "90d" ? 90 : 365
    const cutoff = new Date()
    cutoff.setDate(cutoff.getDate() - days)
    return d >= cutoff
}

function filterContactsList(contacts: DashboardContact[], filters: ContactFilters): DashboardContact[] {
    let result = [...contacts]
    const q = filters.search.trim().toLowerCase()
    if (q) {
        result = result.filter((c) =>
            [c.name, c.organization, c.phone, c.email, c.url, c.notes, c.organization_type].join(" ").toLowerCase().includes(q)
        )
    }
    if (filters.organization !== "all") result = result.filter((c) => c.organization === filters.organization)
    if (filters.organizationType !== "all") result = result.filter((c) => c.organization_type === filters.organizationType)
    if (filters.referralCount !== "all") result = result.filter((c) => passesContactReferralCountFilter(c.referral_count, filters.referralCount))
    if (filters.lastActive !== "all") result = result.filter((c) => passesContactLastActiveFilter(c.last_active_at, filters.lastActive))
    if (filters.source === "referral") result = result.filter((c) => c.source === "referral")
    else if (filters.source === "personal") result = result.filter((c) => c.source === "user")
    return result.sort((a, b) => {
        const aDate = a.last_active_at ? new Date(a.last_active_at).getTime() : 0
        const bDate = b.last_active_at ? new Date(b.last_active_at).getTime() : 0
        if (bDate !== aDate) return bDate - aDate
        return a.name.localeCompare(b.name)
    })
}

function contactListStats(contacts: DashboardContact[]): ContactListStats {
    const weekAgo = new Date()
    weekAgo.setDate(weekAgo.getDate() - 7)
    return {
        total: contacts.length,
        hasReferred: contacts.filter((c) => c.referral_count > 0).length,
        personal: contacts.filter((c) => c.source === "user").length,
        activeThisWeek: contacts.filter((c) => {
            if (!c.last_active_at) return false
            const d = new Date(c.last_active_at)
            return !Number.isNaN(d.getTime()) && d >= weekAgo
        }).length,
        multiReferral: contacts.filter((c) => c.referral_count > 1).length,
    }
}

function directoryEscapeCsv(value: unknown): string {
    if (value === null || value === undefined) return ""
    const text = String(value)
    if (/[",\n\r]/.test(text)) return `"${text.replace(/"/g, '""')}"`
    return text
}

function directoryDownloadCsv(content: string, filename: string) {
    const blob = new Blob([content], { type: "text/csv;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement("a")
    anchor.href = url
    anchor.download = filename
    anchor.click()
    URL.revokeObjectURL(url)
}

function directoryExportTimestamp(): string {
    const d = new Date()
    const pad = (n: number) => String(n).padStart(2, "0")
    return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`
}

function exportOrganizationsCsv(organizations: DashboardOrganization[], referrals: ReferralSubmission[]) {
    if (organizations.length === 0) {
        window.alert("No organizations to export.")
        return
    }
    const cols = [
        "id", "name", "contact_name", "phone", "email", "organization_type", "organization_type_label", "created_at",
        "total_referrals", "active_referrals", "pending_review", "under_review", "accepted", "declined", "waitlisted", "referrals_this_week",
    ] as const
    const rows = organizations.map((org) => {
        const stats = organizationReferralStats(referrals, org)
        const row: Record<string, string | number> = {
            id: org.id, name: org.name, contact_name: org.contact_name, phone: org.phone, email: org.email,
            organization_type: org.organization_type, organization_type_label: ORGANIZATION_TYPE_LABELS[org.organization_type],
            created_at: org.created_at, total_referrals: stats.total, active_referrals: stats.active,
            pending_review: stats.pending_review, under_review: stats.under_review, accepted: stats.accepted,
            declined: stats.declined, waitlisted: stats.waitlisted, referrals_this_week: stats.this_week,
        }
        return cols.map((col) => directoryEscapeCsv(row[col])).join(",")
    })
    directoryDownloadCsv([cols.join(","), ...rows].join("\n"), `monarch_organizations_${organizations.length}-${directoryExportTimestamp()}.csv`)
}

function exportContactsCsv(contacts: DashboardContact[]) {
    if (contacts.length === 0) {
        window.alert("No contacts to export.")
        return
    }
    const cols = ["id", "name", "organization", "organization_type", "organization_type_label", "phone", "email", "url", "notes", "source", "referral_count", "last_active_at", "created_at"] as const
    const rows = contacts.map((contact) => {
        const row: Record<string, string | number> = {
            id: contact.id, name: contact.name, organization: contact.organization, organization_type: contact.organization_type,
            organization_type_label: ORGANIZATION_TYPE_LABELS[contact.organization_type], phone: contact.phone, email: contact.email,
            url: contact.url, notes: contact.notes, source: contact.source, referral_count: contact.referral_count,
            last_active_at: contact.last_active_at ?? "", created_at: contact.created_at,
        }
        return cols.map((col) => directoryEscapeCsv(row[col])).join(",")
    })
    directoryDownloadCsv([cols.join(","), ...rows].join("\n"), `monarch_contacts_${contacts.length}-${directoryExportTimestamp()}.csv`)
}

function readUserDirectoryOrganizations(userId: string | null): DashboardOrganization[] {
    if (!userId || typeof localStorage === "undefined") return []
    try {
        const raw = localStorage.getItem(`${DIRECTORY_ORGS_STORAGE_KEY}-${userId}`)
        return raw ? (JSON.parse(raw) as DashboardOrganization[]) : []
    } catch {
        return []
    }
}

function writeUserDirectoryOrganizations(userId: string | null, orgs: DashboardOrganization[]) {
    if (!userId || typeof localStorage === "undefined") return
    try {
        localStorage.setItem(`${DIRECTORY_ORGS_STORAGE_KEY}-${userId}`, JSON.stringify(orgs.filter((o) => o.source === "user")))
    } catch {
        /* ignore */
    }
}

function readUserDirectoryContacts(userId: string | null): DashboardContact[] {
    if (!userId || typeof localStorage === "undefined") return []
    try {
        const raw = localStorage.getItem(`${DIRECTORY_CONTACTS_STORAGE_KEY}-${userId}`)
        return raw ? (JSON.parse(raw) as DashboardContact[]) : []
    } catch {
        return []
    }
}

function writeUserDirectoryContacts(userId: string | null, contacts: DashboardContact[]) {
    if (!userId || typeof localStorage === "undefined") return
    try {
        localStorage.setItem(`${DIRECTORY_CONTACTS_STORAGE_KEY}-${userId}`, JSON.stringify(contacts.filter((c) => c.source === "user")))
    } catch {
        /* ignore */
    }
}

