function useResolvedDashboardTheme(): "light" | "dark" {
    const [resolved, setResolved] = useState<"light" | "dark">(() =>
        typeof window !== "undefined" ? resolveMonarchThemeMode(getStoredMonarchThemeMode()) : "light"
    )
    useEffect(() => {
        const sync = () => setResolved(resolveMonarchThemeMode(getStoredMonarchThemeMode()))
        sync()
        window.addEventListener("monarch-theme-change", sync)
        const mq = window.matchMedia("(prefers-color-scheme: dark)")
        mq.addEventListener("change", sync)
        return () => {
            window.removeEventListener("monarch-theme-change", sync)
            mq.removeEventListener("change", sync)
        }
    }, [])
    return resolved
}

function DashboardThemeToggle({ collapsed = false }: { collapsed?: boolean }) {
    const resolved = useResolvedDashboardTheme()
    const isDark = resolved === "dark"
    const toggle = () => {
        const next: MonarchThemeMode = isDark ? "light" : "dark"
        applyMonarchThemeMode(next)
    }
    return (
        <button
            type="button"
            onClick={toggle}
            aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
            title={isDark ? "Light mode" : "Dark mode"}
            style={{
                width: collapsed ? "100%" : "auto",
                display: "inline-flex",
                alignItems: "center",
                justifyContent: collapsed ? "center" : "flex-start",
                gap: 10,
                padding: collapsed ? "12px" : "10px 14px",
                fontSize: 13,
                fontWeight: 600,
                fontFamily: FONT,
                border: "none",
                borderRadius: RADIUS.small,
                background: "transparent",
                color: COLORS.onChrome,
                cursor: "pointer",
                boxSizing: "border-box",
            }}
        >
            {isDark ? (
                <svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
                    <circle cx="12" cy="12" r="4" />
                    <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41" />
                </svg>
            ) : (
                <svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
                    <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z" />
                </svg>
            )}
        </button>
    )
}

