function SidebarProgramLogo({ collapsed }: { collapsed: boolean }) {
    const [failed, setFailed] = useState(false)
    const theme = useResolvedDashboardTheme()
    const src = competencySidebarLogoSrc(collapsed, theme)
    if (failed) {
        return (
            <div
                aria-label={ACTIVE_MONARCH_PROGRAM.displayName}
                style={{
                    width: collapsed ? 34 : "100%",
                    maxWidth: collapsed ? 34 : SIDEBAR_LOGO_MAX_WIDTH_PX,
                    height: collapsed ? 34 : SIDEBAR_LOGO_MAX_HEIGHT_PX,
                    minHeight: collapsed ? 34 : SIDEBAR_LOGO_MAX_HEIGHT_PX,
                    borderRadius: RADIUS.small,
                    background: "rgba(255,255,255,0.5)",
                    border: `1px solid ${COLORS.sidebarBorder}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: collapsed ? 13 : 20,
                    fontWeight: 700,
                    color: COLORS.onChrome,
                    flexShrink: 0,
                }}
            >
                {collapsed ? "MC" : "Monarch Competency"}
            </div>
        )
    }
    return (
        <img
            key={src}
            src={src}
            alt={ACTIVE_MONARCH_PROGRAM.displayName}
            onError={() => setFailed(true)}
            style={{
                display: "block",
                width: collapsed ? 34 : "100%",
                maxWidth: collapsed ? 34 : SIDEBAR_LOGO_MAX_WIDTH_PX,
                height: collapsed ? 34 : SIDEBAR_LOGO_MAX_HEIGHT_PX,
                maxHeight: collapsed ? 34 : SIDEBAR_LOGO_MAX_HEIGHT_PX,
                objectFit: "contain",
                objectPosition: collapsed ? "center" : "left center",
                flexShrink: 0,
            }}
        />
    )
}

