const DashboardMyProfilePanel = ({
    onProfileSaved,
    onWelcomeNameUpdate,
}: {
    onProfileSaved: (p: AdmissionsStaffProfile) => void
    onWelcomeNameUpdate: (name: string | null) => void
}) => {
    const [loading, setLoading] = useState(true)
    const [saving, setSaving] = useState(false)
    const [saveMsg, setSaveMsg] = useState<string | null>(null)
    const [saveErr, setSaveErr] = useState<string | null>(null)
    const [userId, setUserId] = useState<string | null>(null)
    const [displayName, setDisplayName] = useState("")
    const [title, setTitle] = useState("")
    const [phone, setPhone] = useState("")
    const [contactEmail, setContactEmail] = useState("")
    const [smsOptIn, setSmsOptIn] = useState(false)

    useEffect(() => {
        let cancelled = false
        ;(async () => {
            setLoading(true)
            setSaveErr(null)
            const { data: { user } } = await supabase.auth.getUser()
            if (!user || cancelled) {
                setLoading(false)
                return
            }
            setUserId(user.id)
            const { data, error } = await supabase.from("admissions_staff_profiles").select("*").eq("user_id", user.id).maybeSingle()
            if (cancelled) return
            if (error) {
                console.warn("[Dashboard] admissions_staff_profiles load:", error)
                setSaveErr(error.message)
                setLoading(false)
                return
            }
            if (data) {
                const p = data as AdmissionsStaffProfile
                setDisplayName(p.display_name || "")
                setTitle(p.title || "")
                setPhone(p.phone || "")
                setContactEmail(p.contact_email || "")
                const prefs = p.notification_preferences
                setSmsOptIn(!!prefs && typeof prefs === "object" && (prefs as { sms_opt_in?: boolean }).sms_opt_in === true)
                onProfileSaved(p)
            } else {
                const metaName = String(user.user_metadata?.full_name || user.user_metadata?.name || "").trim()
                setDisplayName(metaName)
                setTitle("")
                setPhone("")
                setContactEmail("")
                setSmsOptIn(false)
            }
            setLoading(false)
        })()
        return () => { cancelled = true }
        // Mount load only; parent merges profile via onProfileSaved when row exists.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    const handleSave = async () => {
        if (!userId) return
        const ce = contactEmail.trim()
        if (ce && !isStaffEmailForProgram(ce)) {
            setSaveErr(`Work email must be empty or a ${staffEmailDomainsUiList()} address.`)
            return
        }
        setSaving(true)
        setSaveErr(null)
        setSaveMsg(null)
        const notification_preferences = { sms_opt_in: smsOptIn }
        const { data, error } = await supabase.from("admissions_staff_profiles").upsert(
            {
                user_id: userId,
                display_name: displayName.trim() || null,
                title: title.trim() || null,
                phone: phone.trim() || null,
                contact_email: ce || null,
                notification_preferences,
            },
            { onConflict: "user_id" }
        ).select("*").maybeSingle()
        setSaving(false)
        if (error) {
            setSaveErr(error.message)
            return
        }
        if (data) {
            const p = data as AdmissionsStaffProfile
            onProfileSaved(p)
            const dn = displayName.trim()
            await supabase.auth.updateUser({ data: { full_name: dn || undefined } })
            onWelcomeNameUpdate(dn || null)
            setSaveMsg("Profile saved.")
            window.setTimeout(() => setSaveMsg(null), 5000)
        }
    }

    return (
        <>
                <p style={{ margin: "0 0 24px 0", fontSize: "14px", lineHeight: 1.55, color: COLORS.ashMuted, fontFamily: FONT }}>
                    How you appear to referring sources when you are assigned to a referral. Sign-in email is not shown here; use a program work address for published contact when you add one.
                </p>
                {loading ? (
                    <p style={{ margin: 0, fontSize: "14px", color: COLORS.ashMuted, fontFamily: FONT }}>Loading…</p>
                ) : (
                    <div style={{ display: "flex", flexDirection: "column", gap: "18px" }}>
                        {saveErr && (
                            <div style={{ padding: "12px 14px", borderRadius: RADIUS.section, background: COLORS.errorBg, color: COLORS.error, fontSize: "13px", fontFamily: FONT }}>
                                {saveErr}
                            </div>
                        )}
                        {saveMsg && (
                            <div style={{ padding: "12px 14px", borderRadius: RADIUS.section, background: COLORS.successBg, color: COLORS.success, fontSize: "13px", fontFamily: FONT }}>
                                {saveMsg}
                            </div>
                        )}
                        <label style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                            <span style={{ fontSize: "12px", fontWeight: 600, color: COLORS.ashMuted, fontFamily: FONT }}>Full name</span>
                            <input value={displayName} onChange={(e) => setDisplayName(e.target.value)} style={profileTextInputStyle} autoComplete="name" />
                        </label>
                        <label style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                            <span style={{ fontSize: "12px", fontWeight: 600, color: COLORS.ashMuted, fontFamily: FONT }}>Position / title</span>
                            <input value={title} onChange={(e) => setTitle(e.target.value)} style={profileTextInputStyle} autoComplete="organization-title" />
                        </label>
                        <label style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                            <span style={{ fontSize: "12px", fontWeight: 600, color: COLORS.ashMuted, fontFamily: FONT }}>Phone (published)</span>
                            <input value={phone} onChange={(e) => setPhone(e.target.value)} style={profileTextInputStyle} autoComplete="tel" />
                        </label>
                        <label style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                            <span style={{ fontSize: "12px", fontWeight: 600, color: COLORS.ashMuted, fontFamily: FONT }}>Work email (published)</span>
                            <input value={contactEmail} onChange={(e) => setContactEmail(e.target.value)} style={profileTextInputStyle} autoComplete="email" placeholder={`you@${ACTIVE_MONARCH_PROGRAM.staffEmailDomains[0]}`} />
                        </label>
                        <label style={{ display: "flex", alignItems: "center", gap: "10px", cursor: "pointer", fontFamily: FONT, fontSize: "14px", color: COLORS.ash }}>
                            <input type="checkbox" checked={smsOptIn} onChange={(e) => setSmsOptIn(e.target.checked)} style={{ width: "18px", height: "18px", accentColor: COLORS.moonstone }} />
                            SMS updates (optional — notifications not wired yet)
                        </label>
                        <div style={{ display: "flex", gap: "12px", marginTop: "8px", flexWrap: "wrap" }}>
                            <button type="button" onClick={handleSave} disabled={saving} style={{ ...BUTTON_PRIMARY, opacity: saving ? 0.7 : 1 }}>
                                {saving ? "Saving…" : "Save profile"}
                            </button>
                        </div>
                    </div>
                )}
        </>
    )
}

