const StatusDropdown = ({ currentStatus, onUpdate, disabled, compact, table }: {
    currentStatus: string
    onUpdate: (s: ReferralStatus) => void
    disabled?: boolean
    /** @deprecated use table */
    compact?: boolean
    /** Submissions grid: short codes, constrained width (avoids bleed from adjacent cells). */
    table?: boolean
}) => {
    const status = currentStatus || "pending_review"
    const fullLabel = STATUS_OPTIONS.find((o) => o.value === status)?.label || formatLabel(status)
    const shortLabels = table ?? compact
    return (
        <select
            value={status}
            disabled={disabled}
            title={shortLabels ? fullLabel : undefined}
            aria-label={fullLabel}
            onChange={(e) => onUpdate(e.target.value as ReferralStatus)}
            style={{
                ...selectStyle,
                fontSize: "11px",
                padding: shortLabels ? "4px 18px 4px 6px" : "4px 30px 4px 12px",
                backgroundPosition: shortLabels ? "right 6px center" : "right 14px center",
                width: shortLabels ? "100%" : undefined,
                maxWidth: shortLabels ? "100%" : undefined,
                minWidth: shortLabels ? 0 : undefined,
                boxSizing: "border-box",
                opacity: disabled ? 0.6 : 1,
                display: "block",
            }}
        >
            {STATUS_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                    {shortLabels ? (STATUS_TABLE_SHORT[opt.value] || opt.label) : opt.label}
                </option>
            ))}
        </select>
    )
}

