/** Signed URLs for attachment preview / zip (15 minutes). */
const ATTACHMENT_SIGNED_URL_TTL_SEC = 15 * 60

type UploadedDocMeta = {
    storage_path?: string | null
    filename?: string | null
    mime_type?: string | null
    document_type?: string | null
    file_size?: number | null
    uploaded_at?: string | null
}

function attachmentMimeForDoc(doc: UploadedDocMeta): string {
    if (doc.mime_type && typeof doc.mime_type === "string" && doc.mime_type.trim()) return doc.mime_type.trim()
    const n = (doc.filename || "").toLowerCase()
    if (n.endsWith(".pdf")) return "application/pdf"
    if (n.endsWith(".png")) return "image/png"
    if (n.endsWith(".jpg") || n.endsWith(".jpeg")) return "image/jpeg"
    if (n.endsWith(".gif")) return "image/gif"
    if (n.endsWith(".webp")) return "image/webp"
    return "application/octet-stream"
}

function isInlinePreviewableMime(m: string): boolean {
    return m.startsWith("image/") || m === "application/pdf"
}

/** CRC-32 (IEEE) for ZIP — no external deps (Framer bundle cannot resolve `jszip`). */
const CRC32_TABLE: Uint32Array = (() => {
    const t = new Uint32Array(256)
    for (let n = 0; n < 256; n++) {
        let c = n
        for (let k = 0; k < 8; k++) c = c & 1 ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1)
        t[n] = c >>> 0
    }
    return t
})()

function crc32Zip(data: Uint8Array): number {
    let c = 0xffffffff
    for (let i = 0; i < data.length; i++) c = CRC32_TABLE[(c ^ data[i]) & 0xff] ^ (c >>> 8)
    return (c ^ 0xffffffff) >>> 0
}

function dosDateTime(d = new Date()): { dosTime: number; dosDate: number } {
    const y = Math.max(1980, d.getUTCFullYear())
    const dosTime = (d.getUTCHours() << 11) | (d.getUTCMinutes() << 5) | Math.floor(d.getUTCSeconds() / 2)
    const dosDate = ((y - 1980) << 9) | ((d.getUTCMonth() + 1) << 5) | d.getUTCDate()
    return { dosTime, dosDate }
}

/** Minimal ZIP (STORE / uncompressed) for browser + Framer — UTF-8 paths via GPBF 0x0800. */
function buildZipBlobStore(entries: { path: string; data: Uint8Array }[]): Blob {
    const enc = new TextEncoder()
    const { dosTime, dosDate } = dosDateTime()
    const parts: BlobPart[] = []
    const centralParts: Uint8Array[] = []
    let offset = 0

    for (const e of entries) {
        const nameBytes = enc.encode(e.path.replace(/\\/g, "/"))
        const data = e.data
        const crc = crc32Zip(data)
        const sz = data.length
        const localHeader = new Uint8Array(30 + nameBytes.length)
        const v = new DataView(localHeader.buffer)
        let p = 0
        v.setUint32(p, 0x04034b50, true); p += 4
        v.setUint16(p, 20, true); p += 2
        v.setUint16(p, 0x0800, true); p += 2
        v.setUint16(p, 0, true); p += 2
        v.setUint16(p, dosTime, true); p += 2
        v.setUint16(p, dosDate, true); p += 2
        v.setUint32(p, crc, true); p += 4
        v.setUint32(p, sz, true); p += 4
        v.setUint32(p, sz, true); p += 4
        v.setUint16(p, nameBytes.length, true); p += 2
        v.setUint16(p, 0, true); p += 2
        localHeader.set(nameBytes, 30)

        const localOffset = offset
        parts.push(localHeader as BlobPart, data as BlobPart)
        offset += localHeader.length + sz

        const central = new Uint8Array(46 + nameBytes.length)
        const c = new DataView(central.buffer)
        p = 0
        c.setUint32(p, 0x02014b50, true); p += 4
        c.setUint16(p, 0x0314, true); p += 2
        c.setUint16(p, 20, true); p += 2
        c.setUint16(p, 0x0800, true); p += 2
        c.setUint16(p, 0, true); p += 2
        c.setUint16(p, dosTime, true); p += 2
        c.setUint16(p, dosDate, true); p += 2
        c.setUint32(p, crc, true); p += 4
        c.setUint32(p, sz, true); p += 4
        c.setUint32(p, sz, true); p += 4
        c.setUint16(p, nameBytes.length, true); p += 2
        c.setUint16(p, 0, true); p += 2
        c.setUint16(p, 0, true); p += 2
        c.setUint16(p, 0, true); p += 2
        c.setUint16(p, 0, true); p += 2
        c.setUint32(p, 0, true); p += 4
        c.setUint32(p, localOffset, true); p += 4
        central.set(nameBytes, 46)
        centralParts.push(central)
    }

    const centralOffset = offset
    for (const c of centralParts) {
        parts.push(c as BlobPart)
        offset += c.length
    }
    const centralSize = offset - centralOffset
    const eocd = new Uint8Array(22)
    const e = new DataView(eocd.buffer)
    e.setUint32(0, 0x06054b50, true)
    e.setUint16(4, 0, true)
    e.setUint16(6, 0, true)
    e.setUint16(8, entries.length, true)
    e.setUint16(10, entries.length, true)
    e.setUint32(12, centralSize, true)
    e.setUint32(16, centralOffset, true)
    e.setUint16(20, 0, true)
    parts.push(eocd as BlobPart)
    return new Blob(parts, { type: "application/zip" })
}

async function zipReferralSubmissionsAttachments(referrals: ReferralSubmission[]): Promise<void> {
    const zipEntries: { path: string; data: Uint8Array }[] = []
    for (const ref of referrals) {
        const docs = Array.isArray(ref.uploaded_documents) ? (ref.uploaded_documents as UploadedDocMeta[]) : []
        if (docs.length === 0) continue
        const folderKey = (ref.referral_code || ref.admin_ref_id || ref.id.replace(/-/g, "").slice(0, 12) || "referral").replace(/[^\w-]+/g, "_")
        const prefix = `referral-${folderKey}`
        let idx = 0
        for (const doc of docs) {
            if (!doc?.storage_path) continue
            const { data, error } = await supabase.storage
                .from("referral-documents")
                .createSignedUrl(doc.storage_path, ATTACHMENT_SIGNED_URL_TTL_SEC)
            if (error || !data?.signedUrl) continue
            const res = await fetch(data.signedUrl)
            if (!res.ok) continue
            const buf = await res.arrayBuffer()
            const base = (doc.filename || `file-${idx}`).replace(/^[/\\]+/, "").replace(/[/\\]/g, "_")
            zipEntries.push({ path: `${prefix}/${String(idx).padStart(2, "0")}_${base}`, data: new Uint8Array(buf) })
            idx++
        }
    }
    if (zipEntries.length === 0) {
        window.alert(
            "No attachments were added to the ZIP. The selected referral(s) may have no files, or Storage could not create download links (check bucket policies for staff)."
        )
        return
    }
    const blob = buildZipBlobStore(zipEntries)
    const ts = new Date().toISOString().slice(0, 10)
    const a = document.createElement("a")
    a.href = URL.createObjectURL(blob)
    a.download = `monarch-referral-attachments_${ts}.zip`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(a.href)
}

const AttachmentDocRow = ({ doc, index }: { doc: UploadedDocMeta; index: number }) => {
    const [previewOpen, setPreviewOpen] = useState(false)
    const [signedUrl, setSignedUrl] = useState<string | null>(null)
    const [loading, setLoading] = useState(false)
    const [err, setErr] = useState<string | null>(null)

    useEffect(() => {
        if (!previewOpen || !doc.storage_path) return
        let cancelled = false
        setLoading(true)
        setErr(null)
        setSignedUrl(null)
        supabase.storage
            .from("referral-documents")
            .createSignedUrl(doc.storage_path, ATTACHMENT_SIGNED_URL_TTL_SEC)
            .then(({ data, error }) => {
                if (cancelled) return
                setLoading(false)
                if (error || !data?.signedUrl) {
                    setErr("Preview unavailable")
                    return
                }
                setSignedUrl(data.signedUrl)
            })
        return () => {
            cancelled = true
        }
    }, [previewOpen, doc.storage_path])

    const mime = attachmentMimeForDoc(doc)
    const canPreview = isInlinePreviewableMime(mime)

    return (
        <div
            style={{
                fontSize: "13px",
                fontFamily: FONT,
                padding: "10px 12px",
                backgroundColor: index % 2 === 0 ? "var(--card, #FFFFFF)" : "var(--muted, rgba(233, 237, 246, 0.5))",
                borderRadius: RADIUS.small,
                marginBottom: "6px",
                border: `1px solid ${COLORS.ashSubtle}`,
            }}
        >
            <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: "10px", flexWrap: "wrap" }}>
                <div style={{ flex: "1 1 200px", minWidth: 0 }}>
                    {doc.document_type && doc.document_type !== "other" && (
                        <span
                            style={{
                                display: "inline-block",
                                padding: "2px 8px",
                                backgroundColor: COLORS.moonstoneLight,
                                color: COLORS.moonstone,
                                fontSize: "11px",
                                fontWeight: 600,
                                borderRadius: RADIUS.pill,
                                marginRight: "8px",
                                letterSpacing: "0.02em",
                            }}
                        >
                            {formatLabel(doc.document_type)}
                        </span>
                    )}
                    <span style={{ fontWeight: 600 }}>{doc.filename || "File"}</span>
                    <span style={{ color: COLORS.ashMuted, marginLeft: "6px" }}>({Math.round((doc.file_size || 0) / 1024)} KB)</span>
                    <span style={{ color: COLORS.ashMuted, marginLeft: "6px" }}>— {formatDate(doc.uploaded_at)}</span>
                </div>
                <div style={{ display: "flex", gap: "6px", flexShrink: 0, flexWrap: "wrap" }}>
                    {doc.storage_path && canPreview && (
                        <button
                            type="button"
                            onClick={() => setPreviewOpen((o) => !o)}
                            style={{
                                ...pillBtnBase,
                                padding: "4px 10px",
                                fontSize: "11px",
                                background: previewOpen ? COLORS.moonstone : COLORS.coconut,
                                color: previewOpen ? COLORS.white : COLORS.ash,
                            }}
                        >
                            {previewOpen ? "Hide preview" : "Preview"}
                        </button>
                    )}
                    {doc.storage_path && (
                        <button
                            type="button"
                            onClick={async () => {
                                const { data, error } = await supabase.storage
                                    .from("referral-documents")
                                    .createSignedUrl(doc.storage_path!, ATTACHMENT_SIGNED_URL_TTL_SEC)
                                if (error || !data?.signedUrl) {
                                    window.alert("Could not generate download link. Please try again.")
                                    return
                                }
                                const a = document.createElement("a")
                                a.href = data.signedUrl
                                a.download = doc.filename || "download"
                                a.target = "_blank"
                                a.rel = "noopener noreferrer"
                                document.body.appendChild(a)
                                a.click()
                                document.body.removeChild(a)
                            }}
                            style={{ ...pillBtnBase, padding: "4px 10px", fontSize: "11px", background: "transparent", color: COLORS.ash, border: `1px solid ${COLORS.ashSubtle}` }}
                        >
                            Download
                        </button>
                    )}
                </div>
            </div>
            {previewOpen && (
                <div style={{ marginTop: "12px" }}>
                    {loading && <div style={{ fontSize: "12px", color: COLORS.ashMuted }}>Loading preview…</div>}
                    {err && <div style={{ fontSize: "12px", color: COLORS.redText }}>{err}</div>}
                    {signedUrl && mime === "application/pdf" && (
                        <iframe title={doc.filename || "PDF"} src={signedUrl} style={{ width: "100%", height: "min(480px, 55vh)", border: `1px solid ${COLORS.ashSubtle}`, borderRadius: RADIUS.small }} />
                    )}
                    {signedUrl && mime.startsWith("image/") && (
                        <img src={signedUrl} alt="" style={{ maxWidth: "100%", maxHeight: "min(480px, 55vh)", borderRadius: RADIUS.small, border: `1px solid ${COLORS.ashSubtle}` }} />
                    )}
                    {signedUrl && !canPreview && (
                        <a href={signedUrl} target="_blank" rel="noopener noreferrer" style={{ fontSize: "13px", color: COLORS.moonstone, fontWeight: 600 }}>
                            Open file in new tab
                        </a>
                    )}
                </div>
            )}
        </div>
    )
}

