    const [sendingDashboardMessage, setSendingDashboardMessage] = useState(false)
    const [rittenExportNotice, setRittenExportNotice] = useState<string | null>(null)
    /** Set when `staff_program_memberships` is missing so we fall back to listing all submissions (dev / pre-migration). */
    const [submissionsScopeWarning, setSubmissionsScopeWarning] = useState<string | null>(null)
    const [showHelpModal, setShowHelpModal] = useState(false)
    const [showProfileModal, setShowProfileModal] = useState(false)
    const [panelSubmission, setPanelSubmission] = useState<ReferralSubmission | null>(null)
    const [actionsPanelCollapsed, setActionsPanelCollapsed] = useState(true)
    const [panelAssigning, setPanelAssigning] = useState(false)
    const [staffProgramIds, setStaffProgramIds] = useState<string[]>([])
    const [referralTransfers, setReferralTransfers] = useState<ReferralTransferRow[]>([])
    const [transferBusy, setTransferBusy] = useState(false)
    const [transferDialogReferral, setTransferDialogReferral] = useState<ReferralSubmission | null>(null)
    const [transferStaffByProgram, setTransferStaffByProgram] = useState<Record<string, { user_id: string; display_name: string }[]>>({})
    const [userDirectoryOrganizations, setUserDirectoryOrganizations] = useState<DashboardOrganization[]>([])
    const [userDirectoryContacts, setUserDirectoryContacts] = useState<DashboardContact[]>([])
    const [orgSearch, setOrgSearch] = useState("")
