    const [selectedOrgIds, setSelectedOrgIds] = useState<Set<string>>(new Set())
    const [selectedOrganization, setSelectedOrganization] = useState<DashboardOrganization | null>(null)
    const [orgPanelCollapsed, setOrgPanelCollapsed] = useState(true)
    const [contactFilters, setContactFilters] = useState<ContactFilters>(DEFAULT_CONTACT_FILTERS)
    const [selectedContactIds, setSelectedContactIds] = useState<Set<string>>(new Set())
    const [selectedContact, setSelectedContact] = useState<DashboardContact | null>(null)
